/* 7-sinf Kimyo — dars mazmuni (o'zbek / English). Darslik: Zukko International School, 7th grade Chemistry */
window.BOOKS = window.BOOKS || {};
(function () {
  const R = [
    { t: ['6-sinf kimyosini takrorlash', 'Reviewing Grade 6 chemistry'], q: ["6-sinfda qancha kimyo o'rgandik va 7-sinfga qanchalik tayyormiz?", 'How much chemistry have we learned, and how ready are we for Grade 7?'],
      i: ["7-sinfni boshlashdan oldin asosiy tushunchalarni eslaymiz: modda, atom, molekula, agregat holat, fizik va kimyoviy o'zgarishlar.", 'Before starting Grade 7, we recall the key ideas: matter, atom, molecule, states of matter, physical and chemical changes.'],
      p: [["<b>Modda</b> — massaga ega va joy egallaydigan materiya turi.", '<b>Matter</b> is anything that has mass and takes up space.'], ["<b>Atom</b> — kimyoviy elementning eng kichik zarrachasi; <b>molekula</b> — atomlarning birikmasi.", 'An <b>atom</b> is the smallest particle of an element; a <b>molecule</b> is a group of joined atoms.'], ["Muzning erishi, suvning qaynashi — fizik o'zgarish; qog'ozning yonishi, temirning zanglashi — kimyoviy o'zgarish.", 'Ice melting and water boiling are physical changes; paper burning and iron rusting are chemical changes.'], ["Moddalar qattiq, suyuq va gaz holatida bo'ladi.", 'Substances exist as solids, liquids and gases.']],
      k: [['Modda', 'Massaga ega materiya', 'Matter', 'Anything with mass'], ["Fizik o'zgarish", "Yangi modda hosil bo'lmaydi", 'Physical change', 'No new substance forms']],
      z: [["Muzning erishi — fizik o'zgarish.", 'Melting ice is a physical change.', 1], ["Temirning zanglashi — fizik o'zgarish.", 'Iron rusting is a physical change.', 0], ['Molekula atomlardan tuzilgan.', 'A molecule is made of atoms.', 1], ['Gazning o\'z shakli bor.', 'A gas has a fixed shape.', 0]] },

    { t: ['Kimyoning rivojlanishi va zamonaviy kimyo', 'Development of chemistry and modern chemistry'], q: ['Kimyo fani qanday paydo bo\'lgan va qanday rivojlangan?', 'How did chemistry originate and develop?'],
      i: ["Odamlar qadimdan moddalar bilan amaliy tajribalar o'tkazgan: metall eritish, bo'yoq va dori tayyorlash. Bu bilimlar asta-sekin fanga aylandi.", 'People have experimented with substances since ancient times: smelting metals, making dyes and medicines. Gradually this knowledge became a science.'],
      p: [["Qadimgi davr: amaliy tajriba va kuzatish orqali metallar, sopol, bo'yoqlar olingan.", 'Ancient times: metals, pottery and dyes were made through practice and observation.'], ["O'rta asrlar: alkimyogarlar moddalarni o'zgartirishga urinib, ko'plab laboratoriya usullarini yaratdi.", 'Middle Ages: alchemists tried to transform substances and invented many laboratory methods.'], ["XVII–XIX asrlar: tajriba va o'lchashga asoslangan ilmiy kimyo paydo bo'ldi, davriy jadval yaratildi.", '17th–19th centuries: scientific chemistry based on experiments and measurement emerged; the periodic table was created.'], ["Zamonaviy kimyo: yangi materiallar, dorilar, yoqilg'i, suv tozalash va qayta ishlash.", 'Modern chemistry: new materials, medicines, fuels, water purification and recycling.']],
      k: [['Alkimyo', "O'rta asrlardagi moddalarni o'zgartirish haqidagi ta'limot", 'Alchemy', 'Medieval study of transforming substances'], ['Zamonaviy kimyo', "Molekulyar darajada yangi materiallar yaratuvchi fan", 'Modern chemistry', 'Science that designs new materials at the molecular level']],
      f: ['Bugun kimyo tibbiyot, energetika, qishloq xo\'jaligi va ekologiyaning asosi.', 'Today chemistry underpins medicine, energy, agriculture and ecology.'],
      z: [['Kimyo amaliy tajribalardan boshlangan.', 'Chemistry began with practical experiments.', 1], ['Davriy jadval qadimgi davrda yaratilgan.', 'The periodic table was created in ancient times.', 0], ['Zamonaviy kimyo yangi dorilar yaratadi.', 'Modern chemistry creates new medicines.', 1], ['Alkimyogarlar laboratoriya usullarini rivojlantirgan.', 'Alchemists developed laboratory methods.', 1]] },

    { t: ['Sharq olimlari va kimyoning rivojlanishi', 'Eastern scholars and the development of chemistry'], q: ["Sharq olimlari kimyo rivojiga qanday hissa qo'shgan?", 'What did Eastern scholars contribute to chemistry?'],
      i: ["IX–XI asrlarda Sharq olimlari moddalarni tajriba, o'lchash va kuzatish orqali o'rganib, ilmiy yondashuvga asos solishgan.", 'In the 9th–11th centuries, Eastern scholars studied substances through experiment, measurement and observation, laying the foundations of the scientific approach.'],
      p: [["<b>Jobir ibn Hayyon</b> moddalarni aralashtirib, rang o'zgarishlarini sinagan va ko'plab tajribalar o'tkazgan.", '<b>Jabir ibn Hayyan</b> mixed substances, tested colour changes and carried out many experiments.'], ["<b>Ar-Roziy</b> moddalarni guruhlarga ajratgan va laboratoriya jihozlarini takomillashtirgan.", '<b>Al-Razi</b> classified substances and improved laboratory equipment.'], ["<b>Ibn Sino</b> o'simliklardan dorivor moddalar olgan va distillash usulini tasvirlagan.", '<b>Ibn Sina</b> obtained medicines from plants and described distillation.'], ["<b>Beruniy</b> metall va minerallarni to'plab, ularning zichligini aniq o'lchagan; <b>Al-Xorazmiy</b> hisob-kitob usullarini rivojlantirgan.", '<b>Al-Biruni</b> collected metals and minerals and measured their densities precisely; <b>Al-Khwarizmi</b> developed methods of calculation.']],
      k: [['Ilmiy yondashuv', 'Kuzatish → tajriba → o\'lchash → yozib borish → xulosa', 'Scientific approach', 'Observation → experiment → measurement → recording → conclusion']],
      f: ["Beruniyning \"Mineralogiya\" asarida qimmatbaho toshlar va metallar batafsil tasvirlangan.", 'Al-Biruni’s book on mineralogy describes gems and metals in detail.'],
      z: [['Ibn Sino distillash usulini tasvirlagan.', 'Ibn Sina described distillation.', 1], ['Beruniy minerallarni o\'rgangan.', 'Al-Biruni studied minerals.', 1], ["Sharq olimlari tajriba o'tkazmagan.", 'Eastern scholars did not do experiments.', 0], ['Olimlar tajribalarini kitoblarda yozib qoldirgan.', 'The scholars recorded their experiments in books.', 1]] },

    { t: ['Laboratoriyada xavfsiz va aniq ishlash', 'Safe and accurate work in the laboratory'], q: ['Laboratoriyada xavfsizlik va aniqlik nima uchun muhim?', 'Why are safety and accuracy both important in the lab?'],
      i: ['Xavfsizlik + aniqlik + tartib = ishonchli tajriba natijasi!', 'Safety + accuracy + order = a reliable experimental result!'],
      p: [["Himoya ko'zoynagi va xalat kiyiladi, laboratoriyada ovqat yeyilmaydi va ichilmaydi.", 'Wear goggles and a lab coat; never eat or drink in the lab.'], ["Tajribalar faqat o'qituvchi nazoratida o'tkaziladi; biror narsa to'kilsa, darhol xabar beriladi.", 'Experiments are done only under teacher supervision; report any spill at once.'], ["Natijalar daftarga aniq yozib boriladi.", 'Results are recorded accurately in a notebook.'], ["Ish joyi doimo toza va tartibli saqlanadi; tajribadan so'ng jihozlar joyiga qo'yiladi.", 'Keep the workplace clean and tidy; return equipment after the experiment.']],
      k: [['Aniqlik', "O'lchash va yozishda xato qilmaslik", 'Accuracy', 'Measuring and recording without errors'], ['Xavfsizlik', 'Jarohat va baxtsiz hodisalarning oldini olish', 'Safety', 'Preventing injuries and accidents']],
      z: [["Natijalar daftarga aniq yozilishi kerak.", 'Results should be recorded accurately.', 1], ["Tajribani o'qituvchisiz o'tkazish mumkin.", 'Experiments can be done without a teacher.', 0], ['Ish joyi toza saqlanishi kerak.', 'The workplace should be kept clean.', 1], ['Laboratoriyada ichimlik ichish mumkin.', 'You may drink in the lab.', 0]] },

    { t: ['Laboratoriya jihozlari: amaliy ko\'nikmalar', 'Laboratory equipment: practical skills'], q: ['Har bir jihoz qaysi holatda ishlatiladi?', 'When is each piece of equipment used?'],
      i: ["Jihozning nomini bilish yetarli emas — uning vazifasini tushunib, amalda to'g'ri ishlata bilish kerak!", 'Knowing the name of equipment is not enough — you must understand its function and use it correctly!'],
      p: [["<b>Probirka</b> — oz miqdordagi moddalar bilan tajriba; <b>probirka ushlagich</b> — qizdirishda ushlab turish.", '<b>Test tube</b> — experiments with small amounts; <b>test tube holder</b> — holds it while heating.'], ["<b>Kimyoviy stakan</b> va <b>kolba</b> — eritma tayyorlash va aralashtirish; <b>menzurka</b> — suyuqlik hajmini o'lchash.", '<b>Beaker</b> and <b>flask</b> — preparing and mixing solutions; <b>measuring cylinder</b> — measuring liquid volume.'], ["<b>Voronka</b> — quyish va filtrlash; <b>tomizgich (pipetka)</b> — tomchilab qo'shish.", '<b>Funnel</b> — pouring and filtering; <b>dropper (pipette)</b> — adding drop by drop.'], ["<b>Spirt lampasi</b> — qizdirish; <b>shtativ</b> — jihozlarni mahkamlash; <b>chinni hovoncha</b> — moddalarni maydalash.", '<b>Spirit lamp</b> — heating; <b>stand</b> — holding equipment; <b>porcelain mortar</b> — grinding substances.']],
      k: [['Menzurka', "Suyuqlik hajmini o'lchovchi darajalangan silindr", 'Measuring cylinder', 'A graduated cylinder for liquid volume'], ['Shtativ', 'Jihozlarni mahkamlovchi tayanch', 'Stand', 'A support that holds equipment']],
      z: [["Menzurka suyuqlik hajmini o'lchaydi.", 'A measuring cylinder measures liquid volume.', 1], ['Voronka faqat suyuqlik quyish uchun ishlatiladi.', 'A funnel is used only for pouring.', 0, ['Voronka filtrlash uchun ham ishlatiladi.', 'A funnel is also used for filtration.']], ['Probirka ushlagich qizdirishda probirkani ushlaydi.', 'A test tube holder holds a tube while heating.', 1], ['Spirt lampasi o\'lchash uchun ishlatiladi.', 'A spirit lamp is used for measuring.', 0]] },

    { t: ['O\'lchash: massa, hajm va harorat', 'Measurement: mass, volume and temperature'], q: ['Kimyo tajribalarida massa, hajm va harorat nima uchun muhim?', 'Why are mass, volume and temperature important in experiments?'],
      i: ['Aniq o\'lchash — ishonchli tajriba natijasining asosi. Har doim to\'g\'ri jihozdan foydalaning va qoidalarga amal qiling!', 'Accurate measurement is the basis of reliable results. Always use the right equipment and follow the rules!'],
      p: [["<b>Massa</b> — moddadagi materiya miqdori; tarozida grammda (g) o'lchanadi. Tarozi avval nolga keltiriladi (TARE).", '<b>Mass</b> is the amount of matter; measured on a balance in grams (g). Zero (tare) the balance first.'], ["<b>Hajm</b> — modda egallagan joy; menzurkada mL da o'lchanadi. Menisk ko'z darajasida, pastki chizig'i bo'yicha o'qiladi.", '<b>Volume</b> is the space a substance takes up; measured in mL with a measuring cylinder. Read the bottom of the meniscus at eye level.'], ["<b>Harorat</b> — qanchalik issiq yoki sovuqligini bildiradi; termometrda °C da o'lchanadi.", '<b>Temperature</b> shows how hot or cold something is; measured in °C with a thermometer.'], ["Menzurka tik turishi kerak; termometr idish tubiga tegmasligi kerak.", 'Keep the cylinder vertical; the thermometer must not touch the bottom.']],
      k: [['Menisk', 'Suyuqlik yuzasining botiq egriligi', 'Meniscus', 'The curved surface of a liquid'], ['Tare', 'Taroziini nolga keltirish', 'Tare', 'Setting the balance to zero']],
      z: [['Massa grammda o\'lchanadi.', 'Mass is measured in grams.', 1], ["Meniskni yuqoridan qarab o'qish kerak.", 'Read the meniscus from above.', 0], ['Taroziini nolga keltirmaslik xatoga olib keladi.', 'Not zeroing the balance causes errors.', 1], ['Harorat °C da o\'lchanadi.', 'Temperature is measured in °C.', 1]] },

    { t: ['Sof moddalar, aralashmalar va eritmalar', 'Pure substances, mixtures and solutions'], q: ['Moddalar qanday tasniflanadi va ularning farqi nimada?', 'How are substances classified and how do they differ?'],
      i: ['Atrofimizdagi moddalar sof modda yoki aralashma bo\'ladi. Eritma — aralashmaning maxsus turi.', 'Materials around us are pure substances or mixtures. A solution is a special kind of mixture.'],
      p: [["<b>Sof modda</b> — tarkibi va xossalari doimiy (distillangan suv, NaCl, temir).", '<b>Pure substance</b> — constant composition and properties (distilled water, NaCl, iron).'], ["<b>Aralashma</b> — tarkibi o'zgaruvchan bo'lgan ikki yoki undan ortiq modda.", '<b>Mixture</b> — two or more substances with variable composition.'], ["<b>Bir jinsli aralashma</b> (eritma, havo) — bir fazali; <b>ko'p jinsli</b> (qum + suv) — tarkibiy qismlari ko'rinadi.", '<b>Homogeneous mixture</b> (solution, air) — one phase; <b>heterogeneous</b> (sand + water) — parts are visible.'], ["Eritma = erigan modda + erituvchi (ko'pincha suv).", 'Solution = solute + solvent (often water).']],
      k: [['Erituvchi', "Eritmadagi ko'p miqdordagi modda", 'Solvent', 'The substance present in larger amount'], ['Erigan modda', 'Erituvchida eriydigan modda', 'Solute', 'The substance that dissolves']],
      z: [['Eritma — aralashmaning bir turi.', 'A solution is a type of mixture.', 1], ['Havo — bir jinsli aralashma.', 'Air is a homogeneous mixture.', 1], ["Qum + suv — bir jinsli aralashma.", 'Sand + water is a homogeneous mixture.', 0], ['Distillangan suv — sof modda.', 'Distilled water is a pure substance.', 1]] },

    { t: ['Aralashmalarni ajratish usullari', 'Methods for separating mixtures'], q: ['Har bir aralashma uchun qaysi ajratish usuli mos?', 'Which separation method suits each mixture?'],
      i: ['Ajratish usullari moddalarning fizik xossalariga asoslanadi va moddalar tarkibini o\'zgartirmaydi.', 'Separation methods are based on physical properties and do not change the substances.'],
      p: [["<b>Tindirish va dekantatsiya</b> — og'ir zarrachalar cho'kadi, tiniq suyuqlik ehtiyotlik bilan quyib olinadi.", '<b>Settling and decanting</b> — heavy particles sink and the clear liquid is poured off.'], ["<b>Filtrlash</b> — erimagan qattiq modda filtrda qoladi (qum + suv).", '<b>Filtration</b> — an insoluble solid stays on the filter (sand + water).'], ["<b>Bug'latish</b> — eritmadan erigan qattiq moddani olish (tuzli suvdan tuz).", '<b>Evaporation</b> — obtaining a dissolved solid (salt from salt water).'], ["<b>Distillash</b> — bug'ni kondensatsiyalab toza suyuqlik olish; <b>magnit</b> bilan temir kukunini ajratish; <b>xromatografiya</b> — bo'yoqlarni ajratish.", '<b>Distillation</b> — condensing vapour to get a pure liquid; a <b>magnet</b> separates iron filings; <b>chromatography</b> separates dyes.']],
      k: [['Dekantatsiya', 'Cho\'kma ustidagi suyuqlikni quyib olish', 'Decantation', 'Pouring liquid off a sediment'], ["Bug'latish", "Erituvchini bug'latib, erigan moddani olish", 'Evaporation', 'Removing solvent to obtain the solute']],
      z: [['Distillashda bug\' kondensatsiyalanib suyuqlik olinadi.', 'In distillation, vapour is condensed into liquid.', 1], ['Tuzli suvdan tuzni filtrlab olish mumkin.', 'Salt can be filtered out of salt water.', 0], ['Magnit temir kukunini ajratadi.', 'A magnet separates iron filings.', 1], ["Ajratish usullari moddalar tarkibini o'zgartiradi.", 'Separation methods change the composition of substances.', 0]] },

    { t: ["Fizik va kimyoviy o'zgarishlarni tajribada farqlash", 'Distinguishing physical and chemical changes through experiments'], q: ["O'zgarish fizikmi yoki kimyoviy ekanini qanday bilamiz?", 'How can we tell whether a change is physical or chemical?'],
      i: ["Moddalar issiqlik, yorug'lik, bosim ta'sirida o'zgaradi. Ba'zi o'zgarishlarda yangi modda hosil bo'lmaydi, ba'zilarida esa hosil bo'ladi.", 'Substances change under heat, light or pressure. In some changes no new substance forms; in others one does.'],
      p: [["<b>Fizik o'zgarish</b>: faqat ko'rinish, shakl yoki holat o'zgaradi (muz erishi, qog'oz yirtilishi, shakar erishi).", '<b>Physical change</b>: only appearance, shape or state changes (melting ice, tearing paper, dissolving sugar).'], ["<b>Kimyoviy o'zgarish</b>: yangi modda hosil bo'ladi (yog'och yonishi, temir zanglashi, tuxum pishishi).", '<b>Chemical change</b>: a new substance forms (burning wood, rusting, cooking an egg).'], ["Kimyoviy o'zgarish belgilari: rang o'zgarishi, gaz ajralishi, issiqlik chiqishi/yutilishi, cho'kma, yangi hid.", 'Signs of chemical change: colour change, gas, heat given out/taken in, precipitate, new smell.'], ["Sirka + soda tajribasida CO₂ gazi ajraladi — bu kimyoviy o'zgarish.", 'Vinegar + baking soda releases CO₂ gas — a chemical change.']],
      k: [["Fizik o'zgarish", "Yangi modda hosil bo'lmaydigan o'zgarish", 'Physical change', 'A change with no new substance'], ["Kimyoviy o'zgarish", "Yangi modda hosil bo'ladigan o'zgarish", 'Chemical change', 'A change producing a new substance']],
      z: [["Muzning erishi — kimyoviy o'zgarish.", 'Melting ice is a chemical change.', 0], ["Yog'ochning yonishi — kimyoviy o'zgarish.", 'Burning wood is a chemical change.', 1], ["Gaz ajralishi kimyoviy o'zgarish belgisi bo'lishi mumkin.", 'Gas release can be a sign of chemical change.', 1], ["Tuzning suvda erishi — kimyoviy o'zgarish.", 'Dissolving salt is a chemical change.', 0]] },

    { t: ["Atom haqidagi tasavvurlarning rivojlanishi", 'Development of ideas about the atom'], q: ["Atom haqidagi ilmiy g'oyalar vaqt o'tishi bilan qanday o'zgargan va nima uchun?", 'How have scientific ideas about the atom changed over time, and why?'],
      i: ["Atom modeli tajribalar, kuzatishlar va olimlarning g'oyalari asosida rivojlangan. Har bir yangi model avvalgisining kamchiligini to'g'irlagan.", 'The atomic model developed through experiments, observations and scientists’ ideas. Each new model corrected the previous one.'],
      p: [["<b>Demokrit</b> (qadimgi Yunoniston): modda bo'linmas zarrachalar — atomlardan iborat.", '<b>Democritus</b> (ancient Greece): matter is made of indivisible particles — atoms.'], ["<b>Dalton</b> (1803): har bir element bir xil atomlardan iborat; atomlar qattiq sharchalar.", '<b>Dalton</b> (1803): each element is made of identical atoms; atoms are solid spheres.'], ["<b>Tomson</b> (1897): katod nurlari tajribasida elektronni kashf qildi — \"mayizli pirog\" modeli.", '<b>Thomson</b> (1897): discovered the electron with cathode rays — the "plum pudding" model.'], ["<b>Rezerford</b> (1911): oltin varaq tajribasi — kichik zich yadro; <b>Bor</b> (1913): elektronlar aniq energiya qavatlarida; <b>zamonaviy model</b> — elektron buluti.", '<b>Rutherford</b> (1911): gold foil experiment — a tiny dense nucleus; <b>Bohr</b> (1913): electrons in definite energy levels; <b>modern model</b> — the electron cloud.']],
      k: [['Atom modeli', 'Atom tuzilishining ilmiy tasviri', 'Atomic model', 'A scientific picture of atomic structure'], ['Elektron buluti', 'Elektron bo\'lish ehtimoli yuqori soha', 'Electron cloud', 'The region where an electron is likely to be']],
      f: ['Rezerford tajribasida 8000 ta alfa-zarrachadan taxminan bittasi orqaga qaytgan!', 'In Rutherford’s experiment, roughly 1 in 8,000 alpha particles bounced back!'],
      z: [['Tomson elektronni katod nurlari tajribasida kashf qilgan.', 'Thomson discovered the electron with cathode rays.', 1], ["Rezerford atomning asosan bo'shliq ekanini ko'rsatgan.", 'Rutherford showed the atom is mostly empty space.', 1], ['Bor elektronlar aniq energiya qavatlarida harakatlanadi, degan.', 'Bohr proposed electrons occupy definite energy levels.', 1], ['Zamonaviy model elektronlarni aniq orbitada tasvirlaydi.', 'The modern model shows electrons in fixed orbits.', 0]] },

    { t: ['Atomning zamonaviy modeli', 'Modern model of the atom'], q: ['Bugungi kunda atom qanday tasvirlanadi?', 'How is the atom described today?'],
      i: ["Zamonaviy modelga ko'ra, atom markazida musbat yadro, uning atrofida esa elektronlar <b>elektron buluti</b> ko'rinishida joylashgan.", 'According to the modern model, a positive nucleus sits at the centre and electrons surround it as an <b>electron cloud</b>.'],
      p: [["Atom yadrosi protonlar va neytronlardan iborat; deyarli butun massa yadroda.", 'The nucleus contains protons and neutrons; nearly all the mass is in the nucleus.'], ["Elektronlarning aniq o'rnini aniqlab bo'lmaydi — faqat ularni topish ehtimoli yuqori sohani ko'rsatish mumkin.", 'An electron’s exact position cannot be fixed — only the region of high probability.'], ["Neytronlar zaryadsiz, protonlar musbat, elektronlar manfiy zaryadli.", 'Neutrons are uncharged, protons positive, electrons negative.'], ["Soddalik uchun biz hali ham Bor modelidagi qavatlarni chizamiz.", 'For simplicity we still draw Bohr-style shells.']],
      k: [['Yadro', 'Atom markazidagi musbat zaryadli qism', 'Nucleus', 'The positive centre of the atom'], ['Elektron buluti', 'Elektronlar bo\'lish ehtimoli yuqori soha', 'Electron cloud', 'The high-probability region for electrons']],
      z: [['Elektronlar yadro ichida joylashgan.', 'Electrons are inside the nucleus.', 0], ['Neytronlar zaryadsiz zarrachalar.', 'Neutrons are uncharged.', 1], ['Atom massasining asosiy qismi yadroda.', 'Most of an atom’s mass is in the nucleus.', 1], ["Elektron buluti elektron bo'lish ehtimoli yuqori sohani ko'rsatadi.", 'The electron cloud shows where an electron is likely to be.', 1]] },

    { t: ['Atom yadrosi: proton va neytron', 'Atomic nucleus: proton and neutron'], q: ['Atom yadrosi nima va u qaysi zarrachalardan tuzilgan?', 'What is the atomic nucleus and what is it made of?'],
      i: ["Yadro atomga nisbatan juda kichik (taxminan 100 000 marta), lekin atom massasining deyarli hammasi unda to'plangan.", 'The nucleus is tiny compared with the atom (about 100,000 times smaller), yet holds almost all its mass.'],
      p: [["<b>Proton (p⁺)</b>: zaryadi +1, massasi ≈ 1 m.a.b.", '<b>Proton (p⁺)</b>: charge +1, mass ≈ 1 amu.'], ["<b>Neytron (n⁰)</b>: zaryadi 0, massasi ≈ 1 m.a.b.", '<b>Neutron (n⁰)</b>: charge 0, mass ≈ 1 amu.'], ["Proton va neytronlar birgalikda <b>nuklonlar</b> deyiladi.", 'Protons and neutrons together are called <b>nucleons</b>.'], ["Yadro zaryadi protonlar soniga teng va musbat.", 'The nuclear charge equals the number of protons and is positive.']],
      k: [['Nuklon', 'Yadro zarrachasi: proton yoki neytron', 'Nucleon', 'A particle in the nucleus: proton or neutron'], ['m.a.b.', 'Massaning atom birligi', 'amu', 'Atomic mass unit']],
      z: [['Yadroda faqat protonlar bor.', 'The nucleus contains only protons.', 0], ['Neytron zaryadga ega emas.', 'A neutron has no charge.', 1], ['Proton musbat zaryadli.', 'A proton is positively charged.', 1], ['Elektronlar yadro ichida joylashgan.', 'Electrons are located inside the nucleus.', 0]] },

    { t: ['Elektron va elektron qavatlar', 'Electron and electron shells'], q: ['Elektronlar yadro atrofida qanday joylashadi?', 'How are electrons arranged around the nucleus?'],
      i: ["Elektronlar yadro atrofida energiya darajalari — <b>qavatlar</b> (K, L, M…) bo'yicha joylashadi.", 'Electrons are arranged around the nucleus in energy levels — <b>shells</b> (K, L, M…).'],
      p: [["1-qavat (K) ko'pi bilan <b>2</b>, 2-qavat (L) <b>8</b>, 3-qavat (M) dastlabki 20 elementda <b>8</b> tagacha elektron oladi.", 'Shell 1 (K) holds up to <b>2</b>, shell 2 (L) up to <b>8</b>, shell 3 (M) up to <b>8</b> for the first 20 elements.'], ["Masalan: O — 2, 6; Na — 2, 8, 1; Cl — 2, 8, 7.", 'Examples: O — 2, 6; Na — 2, 8, 1; Cl — 2, 8, 7.'], ["Tashqi qavatdagi elektronlar elementning kimyoviy xossalarini belgilaydi.", 'Outer-shell electrons determine an element’s chemical properties.'], ["Elektron massasi juda kichik (protondan ≈ 1840 marta yengil), zaryadi −1.", 'An electron is very light (≈ 1/1840 of a proton) with charge −1.']],
      k: [['Elektron qavat', 'Elektronlarning energiya darajasi', 'Electron shell', 'An energy level for electrons'], ['Valent elektronlar', 'Tashqi qavat elektronlari', 'Valence electrons', 'Electrons in the outer shell']],
      z: [["1-qavat (K) ko'pi bilan 2 ta elektron oladi.", 'Shell K holds at most 2 electrons.', 1], ["Natriy atomida elektronlar 3 ta qavatda joylashgan.", 'Sodium’s electrons are in 3 shells.', 1], ["2, 6 taqsimoti azotga tegishli.", 'The arrangement 2, 6 belongs to nitrogen.', 0, ['2, 6 — kislorod (O).', '2, 6 is oxygen (O).']], ['Elektron musbat zaryadli.', 'An electron is positively charged.', 0]] },

    { t: ['Tartib raqami va yadro zaryadi', 'Atomic number and nuclear charge'], q: ['Elementning tartib raqami nimani bildiradi?', 'What does an element’s atomic number tell us?'],
      i: ["Davriy jadvaldagi tartib raqami (Z) — elementning \"pasporti\": u yadrodagi protonlar sonini ko'rsatadi.", 'The atomic number (Z) is an element’s "passport": it gives the number of protons.'],
      p: [["<b>Z = p</b> — tartib raqami protonlar soniga teng.", '<b>Z = p</b> — the atomic number equals the number of protons.'], ["Yadro zaryadi = <b>+Z</b>. Masalan, kislorod: Z = 8, yadro zaryadi +8.", 'Nuclear charge = <b>+Z</b>. E.g. oxygen: Z = 8, charge +8.'], ["Neytral atomda elektronlar soni = protonlar soni = Z.", 'In a neutral atom, electrons = protons = Z.'], ["Tartib raqami elementni aniq belgilaydi: Z o'zgarsa — boshqa element.", 'Z identifies the element: change Z and you get a different element.']],
      e: ['Z = p = e (neytral atom / neutral atom)'],
      k: [['Tartib raqami (Z)', 'Protonlar soni', 'Atomic number (Z)', 'Number of protons'], ['Yadro zaryadi', 'Yadrodagi musbat zaryad (+Z)', 'Nuclear charge', 'Positive charge of the nucleus (+Z)']],
      z: [['Z protonlar soniga teng.', 'Z equals the number of protons.', 1], ['Kislorodning yadro zaryadi +8.', 'Oxygen’s nuclear charge is +8.', 1], ["Neytral atomda elektronlar soni Z dan ko'p.", 'A neutral atom has more electrons than Z.', 0], ["Z o'zgarsa, element o'zgaradi.", 'Changing Z changes the element.', 1]] },

    { t: ['Massa soni', 'Mass number'], q: ['Massa soni qanday hisoblanadi?', 'How is the mass number calculated?'],
      i: ['Massa soni (A) — yadrodagi nuklonlar (proton + neytron) umumiy soni.', 'The mass number (A) is the total number of nucleons (protons + neutrons).'],
      p: [["<b>A = p + n</b>.", '<b>A = p + n</b>.'], ["Neytronlar soni: <b>n = A − Z</b>.", 'Number of neutrons: <b>n = A − Z</b>.'], ["Belgilanishi: ²³₁₁Na — yuqorida A = 23, pastda Z = 11.", 'Notation: ²³₁₁Na — A = 23 on top, Z = 11 below.'], ["Massa soni butun son, nisbiy atom massasi (Aᵣ) esa kasr bo'lishi mumkin (Cl — 35,5).", 'A is a whole number, while relative atomic mass (Aᵣ) can be a decimal (Cl — 35.5).']],
      e: ['A = p + n ; n = A − Z'],
      k: [['Massa soni (A)', 'Proton va neytronlar yig\'indisi', 'Mass number (A)', 'Sum of protons and neutrons']],
      z: [['Massa soni A = p + n.', 'Mass number A = p + n.', 1], ['Massa soni faqat neytronlar soniga teng.', 'Mass number equals only the number of neutrons.', 0], ['n = A − Z.', 'n = A − Z.', 1], ['²³Na da 12 ta neytron bor.', '²³Na has 12 neutrons.', 1]] },

    { t: ['Proton, neytron va elektronlar sonini aniqlash', 'Determining the number of protons, neutrons and electrons'], q: ['Davriy jadvaldan foydalanib p, n va e ni qanday topamiz?', 'How do we find p, n and e from the periodic table?'],
      i: ["Uch qadam: Z → protonlar va elektronlar; A − Z → neytronlar.", 'Three steps: Z → protons and electrons; A − Z → neutrons.'],
      p: [["Misol: Mg (Z = 12, A = 24): p = 12, e = 12, n = 12.", 'Example: Mg (Z = 12, A = 24): p = 12, e = 12, n = 12.'], ["Misol: Cl (Z = 17, A = 35): p = 17, e = 17, n = 18.", 'Example: Cl (Z = 17, A = 35): p = 17, e = 17, n = 18.'], ["Ionlarda elektronlar soni o'zgaradi: Na⁺ da 10 ta elektron, Cl⁻ da 18 ta.", 'In ions the electron count changes: Na⁺ has 10 electrons, Cl⁻ has 18.'], ["Agar Z = 12 bo'lsa, neytral atomda 12 ta elektron bor.", 'If Z = 12, the neutral atom has 12 electrons.']],
      k: [['Neytral atom', 'Protonlar va elektronlar soni teng atom', 'Neutral atom', 'An atom with equal protons and electrons']],
      z: [['Z protonlar soniga teng.', 'Z equals the number of protons.', 1], ['A — protonlar va neytronlar yig\'indisi.', 'A is the sum of protons and neutrons.', 1], ['Neytral atomda e = p.', 'In a neutral atom e = p.', 1], ['Z = 12 bo\'lsa, atomda 24 ta elektron bor.', 'If Z = 12, the atom has 24 electrons.', 0]] },

    { t: ['Kimyoviy element tushunchasi', 'Understanding the chemical element'], q: ['Element va modda o\'rtasidagi farq nima?', 'What is the difference between an element and a substance?'],
      i: ["Element — \"nima?\" degan savolga javob: atomning turi. Modda esa shu atomlardan tashkil topgan materiya.", 'An element answers "what kind?": a type of atom. A substance is matter made of such atoms.'],
      p: [["<b>Kimyoviy element</b> — protonlari soni (Z) bir xil bo'lgan atomlar turi.", '<b>A chemical element</b> is a type of atom with the same number of protons (Z).'], ["Z = 7 — azot, Z = 8 — kislorod, Z = 11 — natriy.", 'Z = 7 — nitrogen, Z = 8 — oxygen, Z = 11 — sodium.'], ["Bitta element bir nechta moddani hosil qilishi mumkin: kislorod — O₂ va O₃ (ozon).", 'One element can form several substances: oxygen — O₂ and O₃ (ozone).'], ["Har bir modda element emas: suv (H₂O) — ikki elementdan iborat modda.", 'Not every substance is an element: water (H₂O) is made of two elements.']],
      k: [['Element', 'Protonlari soni bir xil atomlar turi', 'Element', 'A type of atom with the same number of protons']],
      z: [['Element protonlar soni bilan aniqlanadi.', 'An element is identified by its number of protons.', 1], ['Har bir modda element hisoblanadi.', 'Every substance is an element.', 0], ['O₂ va O₃ — bitta elementning moddalari.', 'O₂ and O₃ are substances of one element.', 1], ['Z = 8 — kislorod.', 'Z = 8 is oxygen.', 1]] },

    { t: ['Kimyoviy elementlar belgilari', 'Symbols of chemical elements'], q: ['Element belgilari qanday yoziladi va nima uchun o\'zgarmaydi?', 'How are element symbols written and why don’t they change?'],
      i: ["1814-yilda J. Berselius elementlarni lotincha nomining bosh harflari bilan belgilashni taklif qildi. Bu belgilar butun dunyoda bir xil.", 'In 1814, J. Berzelius proposed using the first letters of an element’s Latin name. The symbols are the same worldwide.'],
      p: [["Belgi bitta katta harf yoki katta + kichik harfdan iborat: H, O, C, Na, Cl, Fe.", 'A symbol is one capital letter or a capital + small letter: H, O, C, Na, Cl, Fe.'], ["Ko'p belgilar lotincha nomdan: Na — Natrium, K — Kalium, Fe — Ferrum, Cu — Cuprum, Ag — Argentum, Au — Aurum.", 'Many come from Latin: Na — Natrium, K — Kalium, Fe — Ferrum, Cu — Cuprum, Ag — Argentum, Au — Aurum.'], ["Belgi elementning bitta atomini ham bildiradi.", 'A symbol also stands for one atom of the element.'], ["Xalqaro belgilar tufayli olimlar bir-birini tushunadi.", 'International symbols let scientists everywhere understand each other.']],
      k: [['Kimyoviy belgi', 'Elementning qisqa xalqaro yozuvi', 'Chemical symbol', 'Short international notation of an element']],
      z: [['Fe — temirning belgisi.', 'Fe is the symbol for iron.', 1], ['Na — azotning belgisi.', 'Na is the symbol for nitrogen.', 0, ['Na — natriy; azot — N.', 'Na is sodium; nitrogen is N.']], ['Belgilar butun dunyoda bir xil.', 'Symbols are the same worldwide.', 1], ['Au — oltin.', 'Au is gold.', 1]] },

    { t: ['Nisbiy atom massasi', 'Relative atomic mass'], q: ['Atom massasini qanday solishtiramiz?', 'How do we compare the masses of atoms?'],
      i: ["Atomlar juda yengil, shuning uchun ularning massasi nisbiy taqqoslanadi: uglerod-12 atomi massasining 1/12 qismiga nisbatan.", 'Atoms are extremely light, so their masses are compared relative to 1/12 of the mass of a carbon-12 atom.'],
      p: [["<b>Nisbiy atom massasi (Aᵣ)</b> — atom massasining ¹²C massasining 1/12 qismiga nisbati.", '<b>Relative atomic mass (Aᵣ)</b> — an atom’s mass compared with 1/12 of the mass of ¹²C.'], ["Aᵣ o'lchov birligiga ega emas; qiymatlari davriy jadvalda berilgan.", 'Aᵣ has no unit; values are given in the periodic table.'], ["Aᵣ(H) = 1, Aᵣ(C) = 12, Aᵣ(O) = 16 — uglerod atomi vodoroddan 12 marta og'ir.", 'Aᵣ(H) = 1, Aᵣ(C) = 12, Aᵣ(O) = 16 — a carbon atom is 12 times heavier than hydrogen.'], ["Aᵣ(Cl) = 35,5 — chunki tabiatda ³⁵Cl va ³⁷Cl izotoplari aralashmasi bor.", 'Aᵣ(Cl) = 35.5 because natural chlorine is a mixture of ³⁵Cl and ³⁷Cl.']],
      k: [['Aᵣ', 'Nisbiy atom massasi (birliksiz)', 'Aᵣ', 'Relative atomic mass (no unit)']],
      z: [["Aᵣ o'lchov birligiga ega emas.", 'Aᵣ has no unit.', 1], ["Uglerod atomi vodorod atomidan 12 marta og'ir.", 'A carbon atom is 12 times heavier than hydrogen.', 1], ['Aᵣ qiymatlari davriy jadvalda berilgan.', 'Aᵣ values are in the periodic table.', 1], ['Aᵣ(O) = 8.', 'Aᵣ(O) = 8.', 0]] },

    { t: ['Massaning atom birligi', 'Atomic mass unit'], q: ['Atomlar massasi qanday birlikda ifodalanadi?', 'In what unit are atomic masses expressed?'],
      i: ['Bitta vodorod atomining massasi taxminan 1,66·10⁻²⁴ g. Bunday kichik sonlar bilan ishlash qiyin, shuning uchun maxsus birlik kiritilgan.', 'One hydrogen atom weighs about 1.66·10⁻²⁴ g. Such tiny numbers are hard to use, so a special unit was introduced.'],
      p: [["<b>1 m.a.b. (u)</b> = ¹²C atomi massasining 1/12 qismi ≈ 1,66·10⁻²⁴ g.", '<b>1 amu (u)</b> = 1/12 of the mass of a ¹²C atom ≈ 1.66·10⁻²⁴ g.'], ["Proton va neytron massasi ≈ 1 m.a.b., elektron massasi ≈ 0,00055 m.a.b.", 'Proton and neutron ≈ 1 amu each; electron ≈ 0.00055 amu.'], ["Atomlar massasi m.a.b. da ifodalanadi, Aᵣ esa birliksiz son.", 'Atomic masses are in amu; Aᵣ is a unitless number.'], ["Masalan, kislorod atomining massasi ≈ 16 m.a.b.", 'E.g. an oxygen atom has a mass of ≈ 16 amu.']],
      k: [['m.a.b.', 'Massaning atom birligi = ¹²C massasining 1/12 qismi', 'amu', 'Atomic mass unit = 1/12 of the mass of ¹²C']],
      z: [['Atomlar massasi m.a.b. da ifodalanadi.', 'Atomic masses are expressed in amu.', 1], ['Aᵣ birliksiz kattalik.', 'Aᵣ is a unitless quantity.', 1], ['Elektron massasi protonnikiga teng.', 'An electron’s mass equals a proton’s.', 0], ['1 m.a.b. ¹²C massasining 1/12 qismi.', '1 amu is 1/12 of the mass of ¹²C.', 1]] },

    { t: ['Izotoplar, izobarlar va izotonlar', 'Isotopes, isobars and isotones'], q: ['Atomlar qaysi kattaliklari bo\'yicha o\'xshash yoki farqli bo\'ladi?', 'In which quantities can atoms be alike or different?'],
      i: ["Atomlarni Z, A va n bo'yicha solishtirib, uch xil guruhga ajratish mumkin.", 'Comparing atoms by Z, A and n gives three kinds of relationships.'],
      p: [["<b>Izotoplar</b> — Z bir xil, A va n har xil: ¹²C, ¹³C, ¹⁴C; ¹H, ²H (deyteriy), ³H (tritiy).", '<b>Isotopes</b> — same Z, different A and n: ¹²C, ¹³C, ¹⁴C; ¹H, ²H (deuterium), ³H (tritium).'], ["<b>Izobarlar</b> — A bir xil, Z har xil: ⁴⁰Ar va ⁴⁰Ca.", '<b>Isobars</b> — same A, different Z: ⁴⁰Ar and ⁴⁰Ca.'], ["<b>Izotonlar</b> — n bir xil: ¹⁴C (8n) va ¹⁶O (8n).", '<b>Isotones</b> — same n: ¹⁴C (8n) and ¹⁶O (8n).'], ["Izotoplarning kimyoviy xossalari deyarli bir xil, chunki elektronlar soni teng.", 'Isotopes have almost identical chemistry because their electron numbers are equal.']],
      k: [['Izotop', 'Bir xil Z, har xil A', 'Isotope', 'Same Z, different A'], ['Izobar', 'Bir xil A, har xil Z', 'Isobar', 'Same A, different Z'], ['Izoton', 'Bir xil neytronlar soni', 'Isotone', 'Same number of neutrons']],
      f: ['¹⁴C izotopi qadimiy topilmalarning yoshini aniqlashda ishlatiladi (radiouglerod usuli).', 'Carbon-14 is used to date ancient finds (radiocarbon dating).'],
      z: [['Izotoplarda Z bir xil.', 'Isotopes have the same Z.', 1], ['Izobarlarda A bir xil.', 'Isobars have the same A.', 1], ['¹⁴C va ¹⁶O izotonlar.', '¹⁴C and ¹⁶O are isotones.', 1], ['Izotoplarning protonlar soni har xil.', 'Isotopes have different numbers of protons.', 0]] },

    { t: ['Valentlik', 'Valency'], q: ['Atom boshqa atomlar bilan nechta bog\' hosil qiladi?', 'How many bonds does an atom form with others?'],
      i: ['Valentlik — atomning boshqa atomlar bilan hosil qiladigan kimyoviy bog\'lar soni. U rim raqamlari bilan yoziladi.', 'Valency is the number of chemical bonds an atom forms with other atoms. It is written in Roman numerals.'],
      p: [["Vodorodning valentligi doim <b>I</b>, kislorodniki odatda <b>II</b>.", 'Hydrogen always has valency <b>I</b>; oxygen usually <b>II</b>.'], ["Doimiy valentli: Na, K — I; Mg, Ca, Zn — II; Al — III.", 'Constant valency: Na, K — I; Mg, Ca, Zn — II; Al — III.'], ["O'zgaruvchan valentli: Fe — II, III; Cu — I, II; S — II, IV, VI; C — II, IV; N — I…V.", 'Variable valency: Fe — II, III; Cu — I, II; S — II, IV, VI; C — II, IV; N — I…V.'], ["H₂O da: H — I, O — II; har bir O atomi ikki H bilan bog'langan.", 'In H₂O: H — I, O — II; each O is bonded to two H.']],
      k: [['Valentlik', "Atomning hosil qiladigan bog'lar soni", 'Valency', 'Number of bonds an atom forms']],
      z: [['Vodorodning valentligi I.', 'Hydrogen has valency I.', 1], ['Natriy doim I valentli.', 'Sodium always has valency I.', 1], ['Temirning valentligi faqat II.', 'Iron’s valency is only II.', 0], ['Kislorod odatda II valentli.', 'Oxygen usually has valency II.', 1]] },

    { t: ['Kimyoviy formula va indekslar', 'Chemical formula and indices'], q: ['Kimyoviy formula nimani ko\'rsatadi?', 'What does a chemical formula show?'],
      i: ['Kimyoviy formula moddaning tarkibini belgilar va indekslar yordamida ko\'rsatadi.', 'A chemical formula shows a substance’s composition using symbols and indices.'],
      p: [["<b>Indeks</b> — element belgisining o'ng pastki qismiga yoziladigan raqam, atomlar sonini bildiradi.", 'An <b>index</b> is a small number written to the lower right of a symbol, giving the number of atoms.'], ["H₂O: 2 ta vodorod va 1 ta kislorod atomi; CO₂: 1 C va 2 O.", 'H₂O: 2 hydrogen and 1 oxygen atom; CO₂: 1 C and 2 O.'], ["Indeks 1 bo'lsa, yozilmaydi: NaCl, CO.", 'An index of 1 is not written: NaCl, CO.'], ["<b>Koeffitsiyent</b> formula oldiga yoziladi va molekulalar sonini bildiradi: 3H₂O — 3 ta suv molekulasi.", 'A <b>coefficient</b> goes in front and gives the number of molecules: 3H₂O — three water molecules.']],
      k: [['Indeks', 'Formuladagi atomlar soni', 'Index (subscript)', 'Number of atoms in a formula'], ['Koeffitsiyent', 'Molekulalar soni', 'Coefficient', 'Number of molecules']],
      z: [['Formula moddaning tarkibini ko\'rsatadi.', 'A formula shows composition.', 1], ['Indeks belgining chap tomoniga yoziladi.', 'The index is written to the left of the symbol.', 0], ['NaCl 2 ta atomdan iborat.', 'NaCl consists of 2 atoms.', 1], ['Indeks 1 bo\'lsa yoziladi (O₁).', 'An index of 1 is written (O₁).', 0]] },

    { t: ['Molekula. Nisbiy molekulyar massa (Mᵣ)', 'Molecule. Relative molecular mass (Mᵣ)'], q: ['Molekulaning massasini qanday hisoblaymiz?', 'How do we calculate a molecule’s mass?'],
      i: ['Molekula — moddaning kimyoviy xossalarini saqlovchi eng kichik zarracha. Uning nisbiy massasi atomlar massalari yig\'indisiga teng.', 'A molecule is the smallest particle keeping a substance’s chemical properties. Its relative mass is the sum of its atoms’ masses.'],
      p: [["Molekula bir xil (O₂, H₂, N₂) yoki har xil (H₂O, CO₂) atomlardan iborat bo'ladi.", 'Molecules are made of the same (O₂, H₂, N₂) or different (H₂O, CO₂) atoms.'], ["<b>Mᵣ = Σ(Aᵣ · n)</b> — har bir element Aᵣ i indeksiga ko'paytirilib, qo'shiladi.", '<b>Mᵣ = Σ(Aᵣ · n)</b> — multiply each Aᵣ by its index and add.'], ["Mᵣ(H₂O) = 2·1 + 16 = 18; Mᵣ(CO₂) = 12 + 2·16 = 44.", 'Mᵣ(H₂O) = 2·1 + 16 = 18; Mᵣ(CO₂) = 12 + 2·16 = 44.'], ["Mᵣ birliksiz kattalik.", 'Mᵣ has no unit.']],
      e: ['Mᵣ(H₂O) = 2·1 + 16 = 18', 'Mᵣ(CO₂) = 12 + 2·16 = 44'],
      k: [['Mᵣ', 'Nisbiy molekulyar massa', 'Mᵣ', 'Relative molecular mass']],
      z: [['Molekula moddaning kimyoviy xossalarini saqlaydi.', 'A molecule keeps the chemical properties of a substance.', 1], ['O₂ molekulasi ikki kislorod atomidan iborat.', 'An O₂ molecule has two oxygen atoms.', 1], ['Mᵣ(H₂O) = 18.', 'Mᵣ(H₂O) = 18.', 1], ['Mᵣ g/mol da o\'lchanadi.', 'Mᵣ is measured in g/mol.', 0]] },

    { t: ['Amaliy mashg\'ulot: nisbiy molekulyar massani hisoblash', 'Practical activity: calculating relative molecular mass'], q: ['Turli darajadagi masalalarda Mᵣ ni qanday topamiz?', 'How do we find Mᵣ in problems of different levels?'],
      i: ['Qoida: avval ko\'paytiring, keyin qo\'shing. Indeks bo\'lmasa — 1 deb oling. Hisobni tekshiring!', 'Rule: multiply first, then add. No index means 1. Check your calculation!'],
      p: [["Mᵣ(N₂) = 2·14 = 28; Mᵣ(NH₃) = 14 + 3·1 = 17.", 'Mᵣ(N₂) = 2·14 = 28; Mᵣ(NH₃) = 14 + 3·1 = 17.'], ["Mᵣ(SO₂) = 32 + 2·16 = 64; Mᵣ(H₂SO₄) = 2 + 32 + 64 = 98.", 'Mᵣ(SO₂) = 32 + 2·16 = 64; Mᵣ(H₂SO₄) = 2 + 32 + 64 = 98.'], ["Mᵣ(CaCO₃) = 40 + 12 + 3·16 = 100.", 'Mᵣ(CaCO₃) = 40 + 12 + 3·16 = 100.'], ["Qavsli formulalarda qavs ichidagi har bir atom qavs tashqarisidagi indeksga ko'paytiriladi: Ca(OH)₂ = 40 + 2·(16 + 1) = 74.", 'For brackets, multiply everything inside by the outside index: Ca(OH)₂ = 40 + 2·(16 + 1) = 74.']],
      e: ['Mᵣ(H₂SO₄) = 2·1 + 32 + 4·16 = 98'],
      z: [['Mᵣ(NH₃) = 17.', 'Mᵣ(NH₃) = 17.', 1], ['Mᵣ(CO₂) = 28.', 'Mᵣ(CO₂) = 28.', 0], ['CO₂ molekulasida 1 C va 2 O atomi bor.', 'CO₂ contains 1 C and 2 O atoms.', 1], ['Indeks bo\'lmasa, u 1 deb olinadi.', 'No index means 1.', 1]] },

    { t: ['Moddalarning tasnifi', 'Classification of substances'], q: ['Moddalarni nima uchun va qanday tasniflaymiz?', 'Why and how do we classify substances?'],
      i: ['Modda — aniq tarkib va o\'ziga xos xossalarga ega materiya turi. Moddalar tarkibiga ko\'ra guruhlarga ajratiladi.', 'A substance is matter with a definite composition and specific properties. Substances are grouped by composition.'],
      p: [["Moddalar <b>sof moddalar</b> va <b>aralashmalar</b>ga bo'linadi.", 'Matter is divided into <b>pure substances</b> and <b>mixtures</b>.'], ["Sof moddalar: <b>oddiy</b> (bitta element: O₂, Fe) va <b>murakkab</b> (bir necha element: H₂O, NaCl).", 'Pure substances: <b>simple</b> (one element: O₂, Fe) and <b>compound</b> (several elements: H₂O, NaCl).'], ["Oddiy moddalar metallar va nometallarga bo'linadi.", 'Simple substances are metals or non-metals.'], ["Tasnif moddalarni o'rganish va xossalarini oldindan bilishni osonlashtiradi.", 'Classification makes substances easier to study and their properties easier to predict.']],
      k: [['Oddiy modda', 'Bitta element atomlaridan tuzilgan modda', 'Simple substance', 'Made of atoms of one element'], ['Murakkab modda', 'Bir necha element atomlaridan tuzilgan modda', 'Compound', 'Made of atoms of several elements']],
      z: [['Havodagi kislorod — oddiy modda.', 'Oxygen in air is a simple substance.', 1], ['Ichimlik suvi tarkibidagi H₂O — murakkab modda.', 'H₂O in drinking water is a compound.', 1], ['Metan (CH₄) — oddiy modda.', 'Methane (CH₄) is a simple substance.', 0], ['Moddalar tarkibiga ko\'ra tasniflanadi.', 'Substances are classified by composition.', 1]] },

    { t: ['Oddiy va murakkab moddalar: xossalari va farqlari', 'Simple and compound substances: properties and differences'], q: ['Oddiy va murakkab moddalar qanday farqlanadi?', 'How do simple and compound substances differ?'],
      i: ['Element — atom turi, oddiy modda — shu atomlardan tuzilgan haqiqiy modda. Masalan, kislorod elementi O₂ gazini hosil qiladi.', 'An element is a type of atom; a simple substance is real matter made of those atoms. Oxygen the element forms oxygen gas, O₂.'],
      p: [["Oddiy moddalar: Fe, Cu, Al (metallar); O₂, N₂, H₂, S, C (nometallar).", 'Simple substances: Fe, Cu, Al (metals); O₂, N₂, H₂, S, C (non-metals).'], ["Murakkab moddalarning xossalari ularni tashkil etgan elementlarnikidan butunlay farq qiladi: Na (faol metall) + Cl₂ (zaharli gaz) → NaCl (osh tuzi).", 'Compounds have totally different properties from their elements: Na (reactive metal) + Cl₂ (toxic gas) → NaCl (table salt).'], ["<b>Allotropiya</b>: bitta element bir nechta oddiy modda hosil qiladi — olmos va grafit (C), O₂ va O₃.", '<b>Allotropy</b>: one element forms several simple substances — diamond and graphite (C), O₂ and O₃.'], ["Murakkab moddalarni kimyoviy reaksiya bilan oddiyroq moddalarga ajratish mumkin.", 'Compounds can be broken down by chemical reactions.']],
      k: [['Allotropiya', 'Bitta elementning bir necha oddiy modda hosil qilishi', 'Allotropy', 'One element forming several simple substances']],
      z: [['Fe — oddiy modda.', 'Fe is a simple substance.', 1], ['Olmos va grafit — turli oddiy moddalar.', 'Diamond and graphite are different simple substances.', 1], ['Oddiy moddalar faqat metallardan iborat.', 'Simple substances are only metals.', 0], ['NaCl — murakkab modda.', 'NaCl is a compound.', 1]] },

    { t: ['Modda miqdori. Mol tushunchasi', 'Amount of substance. The concept of the mole'], q: ['Kimyoda juda ko\'p zarrachalarni sanash uchun mol nima uchun qulay?', 'Why is the mole a convenient unit for counting huge numbers of particles?'],
      i: ['Zarrachalarni donalab sanab bo\'lmaydi — ular juda ko\'p. Shuning uchun kimyogarlar "o\'nlik", "duzina" kabi maxsus o\'lchov — molni ishlatadi.', 'Particles are far too many to count one by one, so chemists use a special counting unit — the mole — like a "dozen".'],
      p: [["<b>Modda miqdori (n)</b> — moddadagi zarrachalar sonini ko'rsatuvchi fizik kattalik. Birligi — <b>mol</b>.", '<b>Amount of substance (n)</b> shows the number of particles. Its unit is the <b>mole</b> (mol).'], ["1 mol — 6,02·10²³ ta zarracha (atom, molekula, ion).", '1 mole = 6.02·10²³ particles (atoms, molecules, ions).'], ["n = N / Nₐ — zarrachalar sonidan mol topiladi.", 'n = N / Nₐ — moles from the number of particles.'], ["2 mol H₂O da 2 · 6,02·10²³ = 1,204·10²⁴ ta molekula bor.", '2 mol H₂O contains 2 · 6.02·10²³ = 1.204·10²⁴ molecules.']],
      e: ['n = N / Nₐ'],
      k: [['Mol', '6,02·10²³ ta zarracha tutgan modda miqdori', 'Mole', 'Amount containing 6.02·10²³ particles']],
      z: [['Modda miqdori molda o\'lchanadi.', 'Amount of substance is measured in moles.', 1], ['1 mol da 6,02·10²³ ta zarracha bor.', '1 mole contains 6.02·10²³ particles.', 1], ['1 mol temir va 1 mol suvda zarrachalar soni har xil.', '1 mol of iron and 1 mol of water contain different numbers of particles.', 0], ['n = N / Nₐ.', 'n = N / Nₐ.', 1]] },

    { t: ['Avogadro doimiysi', "Avogadro's constant"], q: ['1 molda nechta zarracha bor?', 'How many particles are in 1 mole?'],
      i: ['Avogadro doimiysi (Nₐ) — 1 mol moddadagi zarrachalar soni. Turli moddalarning 1 molida zarrachalar soni bir xil!', 'Avogadro’s constant (Nₐ) is the number of particles in 1 mole. One mole of any substance has the same number of particles!'],
      p: [["<b>Nₐ = 6,02·10²³ mol⁻¹</b>.", '<b>Nₐ = 6.02·10²³ mol⁻¹</b>.'], ["N = n · Nₐ: 3 mol O₂ da 3 · 6,02·10²³ = 1,806·10²⁴ molekula.", 'N = n · Nₐ: 3 mol O₂ contains 3 · 6.02·10²³ = 1.806·10²⁴ molecules.'], ["H₂O — molekulalardan, NaCl — formula birliklaridan (ionlardan) tuzilgan.", 'H₂O is made of molecules; NaCl of formula units (ions).'], ["Bu son italyan olimi Amedeo Avogadro sharafiga nomlangan.", 'The number is named after the Italian scientist Amedeo Avogadro.']],
      e: ['N = n · Nₐ ; Nₐ = 6,02·10²³ mol⁻¹'],
      k: [['Avogadro doimiysi', '1 moldagi zarrachalar soni', "Avogadro's constant", 'Number of particles in 1 mole']],
      f: ['Agar 6,02·10²³ ta qum donini Yer yuziga sepsak, butun sayyorani bir necha metr qalinlikda qoplardi!', 'If you spread 6.02·10²³ grains of sand over Earth, they would cover the whole planet several metres deep!'],
      z: [['Nₐ = 6,02·10²³.', 'Nₐ = 6.02·10²³.', 1], ['1,5 mol H₂O da 9,03·10²³ molekula bor.', '1.5 mol of H₂O contains 9.03·10²³ molecules.', 1], ['Turli moddalar 1 molida zarrachalar soni turlicha.', 'Different substances have different particle numbers in 1 mole.', 0], ['NaCl formula birliklaridan tuzilgan.', 'NaCl is made of formula units.', 1]] },

    { t: ['Moddaning molyar massasi', 'Molar mass of a substance'], q: ['Nega turli moddalarning 1 moli har xil massaga ega?', 'Why does 1 mole of different substances have different masses?'],
      i: ['1 mol vodorod va 1 mol temirda zarrachalar soni bir xil, lekin temir atomlari og\'irroq — shuning uchun 1 mol temir og\'irroq.', '1 mol of hydrogen and 1 mol of iron have the same number of particles, but iron atoms are heavier — so 1 mol of iron weighs more.'],
      p: [["<b>Molyar massa (M)</b> — 1 mol moddaning massasi; birligi <b>g/mol</b>.", '<b>Molar mass (M)</b> is the mass of 1 mole; unit <b>g/mol</b>.'], ["M son jihatdan Mᵣ ga teng: M(H₂O) = 18 g/mol, M(CO₂) = 44 g/mol, M(Fe) = 56 g/mol.", 'M is numerically equal to Mᵣ: M(H₂O) = 18 g/mol, M(CO₂) = 44 g/mol, M(Fe) = 56 g/mol.'], ["<b>n = m / M</b>: 36 g suv = 36 / 18 = 2 mol.", '<b>n = m / M</b>: 36 g water = 36 / 18 = 2 mol.'], ["88 g CO₂ = 88 / 44 = 2 mol; 56 g Fe = 1 mol.", '88 g CO₂ = 2 mol; 56 g Fe = 1 mol.']],
      e: ['n = m / M ; m = n · M'],
      k: [['Molyar massa', '1 mol moddaning massasi (g/mol)', 'Molar mass', 'Mass of 1 mole (g/mol)']],
      z: [['Molyar massa M bilan belgilanadi.', 'Molar mass is denoted M.', 1], ['Molyar massa birligi g/mol.', 'The unit of molar mass is g/mol.', 1], ['1 mol Fe ning massasi 56 g.', '1 mol of Fe has a mass of 56 g.', 1], ['36 g suv — 1 mol.', '36 g of water is 1 mol.', 0]] },

    { t: ["Amaliy usul: birikmalarda elementlar valentligini aniqlash", 'Practical method: determining the valency of elements in compounds'], q: ['Formuladan valentlikni qanday topamiz?', 'How do we find valency from a formula?'],
      i: ['Birikmada bir elementning umumiy valentlik birliklari ikkinchi elementnikiga teng bo\'ladi.', 'In a compound, the total valency units of one element equal those of the other.'],
      p: [["Qoida: valentlik(A) · indeks(A) = valentlik(B) · indeks(B).", 'Rule: valency(A) · index(A) = valency(B) · index(B).'], ["Al₂O₃: O — II, jami 3·2 = 6; Al: 6 / 2 = III.", 'Al₂O₃: O — II, total 3·2 = 6; Al: 6 / 2 = III.'], ["FeCl₃ da Fe — III, FeCl₂ da Fe — II (Cl — I).", 'In FeCl₃ Fe is III; in FeCl₂ Fe is II (Cl — I).'], ["CO₂ da C — IV; H₂S da H — I, S — II.", 'In CO₂ C is IV; in H₂S H is I and S is II.']],
      z: [['H₂S da vodorodning valentligi I.', 'In H₂S hydrogen has valency I.', 1], ['CO₂ da uglerodning valentligi II.', 'In CO₂ carbon has valency II.', 0], ['Al₂O₃ da alyuminiy III valentli.', 'In Al₂O₃ aluminium has valency III.', 1], ['Temir faqat II valentli.', 'Iron only has valency II.', 0]] },

    { t: ['Amaliy usul: kimyoviy formulalarga oid masalalar', 'Practical method: problems based on chemical formulas'], q: ['Formula asosida qanday hisob-kitoblar qilish mumkin?', 'What calculations can be done from a formula?'],
      i: ['Formula moddaning tarkibini ko\'rsatadi: qaysi elementlar, har biridan nechta atom va Mᵣ qancha.', 'A formula shows which elements are present, how many atoms of each, and lets us compute Mᵣ.'],
      p: [["Qadamlar: (1) elementlarni aniqlang; (2) atomlar sonini toping; (3) kerak bo'lsa Mᵣ ni hisoblang.", 'Steps: (1) identify the elements; (2) count the atoms; (3) calculate Mᵣ if needed.'], ["NaHCO₃: 4 xil element, 6 ta atom, Mᵣ = 23 + 1 + 12 + 48 = 84.", 'NaHCO₃: 4 elements, 6 atoms, Mᵣ = 23 + 1 + 12 + 48 = 84.'], ["Elementning massa ulushi: ω = (Aᵣ · n) / Mᵣ · 100%. H₂O da ω(O) = 16/18 ≈ 89%.", 'Mass fraction: ω = (Aᵣ · n) / Mᵣ · 100%. In H₂O ω(O) = 16/18 ≈ 89%.'], ["Valentlik bo'yicha formula tuzish: Al(III) va O(II) → Al₂O₃.", 'Writing formulas from valency: Al(III) and O(II) → Al₂O₃.']],
      e: ['ω(element) = Aᵣ · n / Mᵣ · 100%'],
      z: [['Formula moddaning tarkibini ko\'rsatadi.', 'A formula shows composition.', 1], ['Formula har bir element atomlari sonini ko\'rsatadi.', 'A formula shows the number of atoms of each element.', 1], ['Mᵣ(NaHCO₃) = 84.', 'Mᵣ(NaHCO₃) = 84.', 1], ['NaHCO₃ da 3 ta atom bor.', 'NaHCO₃ contains 3 atoms.', 0]] },

    { t: ['Kimyoviy reaksiya tenglamalarini yozish', 'Writing chemical reaction equations'], q: ["Moddalardagi o'zgarishlarni tenglama bilan qanday ko'rsatamiz?", 'How do we show changes in substances with equations?'],
      i: ["Kimyoviy tenglama reaksiyaning ramziy yozuvi: chapda reagentlar, o'ngda mahsulotlar. Massaning saqlanish qonuniga ko'ra atomlar soni teng bo'lishi kerak.", 'A chemical equation is a symbolic record: reactants on the left, products on the right. By the law of conservation of mass, atom numbers must balance.'],
      p: [["<b>Massaning saqlanish qonuni</b> (Lomonosov, Lavuazye): reaksiyaga kirgan moddalar massasi hosil bo'lgan moddalar massasiga teng.", '<b>Law of conservation of mass</b> (Lomonosov, Lavoisier): mass of reactants = mass of products.'], ["Atomlar sonini tenglash uchun <b>koeffitsiyentlar</b> qo'yiladi: 2H₂ + O₂ → 2H₂O.", '<b>Coefficients</b> balance the atoms: 2H₂ + O₂ → 2H₂O.'], ["Metan yonishi: CH₄ + 2O₂ → CO₂ + 2H₂O.", 'Methane burning: CH₄ + 2O₂ → CO₂ + 2H₂O.'], ["Indekslarni o'zgartirib bo'lmaydi — faqat koeffitsiyentlar!", 'Never change subscripts — only coefficients!']],
      e: ['2H₂ + O₂ → 2H₂O', 'CH₄ + 2O₂ → CO₂ + 2H₂O', '4Al + 3O₂ → 2Al₂O₃'],
      k: [['Kimyoviy tenglama', 'Reaksiyaning formulalar bilan yozilishi', 'Chemical equation', 'A reaction written with formulas'], ['Koeffitsiyent', 'Formula oldidagi son', 'Coefficient', 'A number in front of a formula']],
      z: [['Tenglamada reagentlar chapda yoziladi.', 'Reactants are written on the left.', 1], ['Atomlar soni teng bo\'lishi shart emas.', 'Atom numbers need not be equal.', 0], ['1 mol CH₄ yonishi uchun 2 mol O₂ kerak.', 'Burning 1 mol CH₄ needs 2 mol O₂.', 1], ['Tenglashda indekslar o\'zgartiriladi.', 'Subscripts are changed to balance.', 0]] },

    { t: ['Amaliy usul: kimyoviy tenglamalar yozish mashqlari', 'Practical method: exercises on writing chemical equations'], q: ["So'zli ifodani tenglamaga qanday aylantiramiz?", 'How do we turn a word equation into a balanced equation?'],
      i: ['Qadamlar: (1) reaksiyani so\'zlar bilan tahlil qiling; (2) formulalarni to\'g\'ri yozing; (3) koeffitsiyentlar bilan tenglang; (4) tekshiring.', 'Steps: (1) analyse the reaction in words; (2) write correct formulas; (3) balance with coefficients; (4) check.'],
      p: [["Natriy + xlor → natriy xlorid: 2Na + Cl₂ → 2NaCl.", 'Sodium + chlorine → sodium chloride: 2Na + Cl₂ → 2NaCl.'], ["Oltingugurt + kislorod → oltingugurt dioksid: S + O₂ → SO₂.", 'Sulfur + oxygen → sulfur dioxide: S + O₂ → SO₂.'], ["Fosfor + kislorod → fosfor(V) oksid: 4P + 5O₂ → 2P₂O₅.", 'Phosphorus + oxygen → phosphorus(V) oxide: 4P + 5O₂ → 2P₂O₅.'], ["Ohaktoshning parchalanishi: CaCO₃ → CaO + CO₂; ammiak sintezi: N₂ + 3H₂ → 2NH₃.", 'Decomposing limestone: CaCO₃ → CaO + CO₂; ammonia synthesis: N₂ + 3H₂ → 2NH₃.']],
      e: ['2Na + Cl₂ → 2NaCl', 'Mg + Cl₂ → MgCl₂', '4P + 5O₂ → 2P₂O₅'],
      z: [['2Na + Cl₂ → 2NaCl tenglashtirilgan.', '2Na + Cl₂ → 2NaCl is balanced.', 1], ['N₂ + H₂ → NH₃ tenglashtirilgan.', 'N₂ + H₂ → NH₃ is balanced.', 0], ['CaCO₃ → CaO + CO₂ — parchalanish reaksiyasi.', 'CaCO₃ → CaO + CO₂ is a decomposition.', 1], ['Har bir tenglamada koeffitsiyent bo\'lishi shart.', 'Every equation must have coefficients.', 0, ['S + O₂ → SO₂ da koeffitsiyent kerak emas.', 'S + O₂ → SO₂ needs no coefficients.']]] },

    { t: ['Kimyoviy elementlarning tasnifi', 'Classification of chemical elements'], q: ['Elementlarni qanday tasniflaymiz?', 'How do we classify elements?'],
      i: ['Har bir element o\'ziga xos xossalarga ega. Tasniflashda nomi, belgisi, atom massasi va xossalari hisobga olinadi.', 'Each element has unique properties. Classification considers name, symbol, atomic mass and properties.'],
      p: [["Elementlar <b>metallar</b> (Na, Fe, Cu), <b>nometallar</b> (O, N, S, Cl) va <b>inert gazlar</b>ga (He, Ne, Ar) bo'linadi.", 'Elements are <b>metals</b> (Na, Fe, Cu), <b>non-metals</b> (O, N, S, Cl) and <b>noble gases</b> (He, Ne, Ar).'], ["Metallar: yaltiroq, issiqlik va elektrni yaxshi o'tkazadi, bolg'alanuvchan.", 'Metals: shiny, good conductors of heat and electricity, malleable.'], ["Nometallar: ko'pincha mo'rt yoki gaz, tok o'tkazmaydi (grafit bundan mustasno).", 'Non-metals: often brittle or gaseous, poor conductors (except graphite).'], ["Ba'zi elementlar oraliq xossaga ega — amfoter (Al, Zn).", 'Some elements show intermediate (amphoteric) behaviour (Al, Zn).']],
      k: [['Metall', 'Yaltiroq, tok o\'tkazuvchi element', 'Metal', 'A shiny, conducting element'], ['Nometall', 'Odatda tok o\'tkazmaydigan element', 'Non-metal', 'An element that usually doesn’t conduct']],
      z: [['Mis — metall.', 'Copper is a metal.', 1], ['Oltingugurt — metall.', 'Sulfur is a metal.', 0], ['Metallar elektr tokini yaxshi o\'tkazadi.', 'Metals conduct electricity well.', 1], ['Neon — inert gaz.', 'Neon is a noble gas.', 1]] },

    { t: ['Elementlar tasnifidagi davriy qonuniyatlar', 'Periodic patterns in the classification of elements'], q: ['Elementlar tasnifi qanday shakllangan?', 'How did the classification of elements develop?'],
      i: ['Elementlar tasnifi birdaniga paydo bo\'lmagan — u ko\'plab olimlarning tajriba va g\'oyalari asosida bosqichma-bosqich shakllangan.', 'The classification did not appear at once — it developed step by step from many scientists’ work.'],
      p: [["<b>R. Boyl</b> tajribaviy usullarni rivojlantirdi; <b>A. Lavuazye</b> kimyoviy element (oddiy modda) tushunchasini kiritib, elementlarni guruhladi.", '<b>R. Boyle</b> developed experimental methods; <b>A. Lavoisier</b> introduced the idea of a chemical element and grouped elements.'], ["<b>J. Dalton</b> atom nazariyasini yaratdi; <b>J. Nyulends</b> elementlarni atom massasi bo'yicha tartibladi (\"oktavalar qonuni\").", '<b>J. Dalton</b> created atomic theory; <b>J. Newlands</b> ordered elements by atomic mass ("law of octaves").'], ["<b>D. I. Mendeleyev</b> (1869) davriy qonunni kashf qilib, hali ochilmagan elementlar uchun bo'sh joy qoldirdi.", '<b>D. I. Mendeleev</b> (1869) discovered the periodic law and left gaps for undiscovered elements.'], ["Bugun elementlar yadro zaryadi (Z) ortib borishi tartibida joylashtiriladi.", 'Today elements are ordered by increasing nuclear charge (Z).']],
      k: [['Davriy qonun', "Elementlar xossalari yadro zaryadiga bog'liq ravishda davriy takrorlanadi", 'Periodic law', 'Element properties repeat periodically with nuclear charge']],
      z: [['Lavuazye ko\'plab elementlarni tajriba orqali aniqlagan.', 'Lavoisier identified many elements by experiment.', 1], ['Dalton atom nazariyasini ishlab chiqqan.', 'Dalton developed atomic theory.', 1], ['Nyulends elementlarni atom massasi bo\'yicha tartiblagan.', 'Newlands ordered elements by atomic mass.', 1], ['Elementlar tasnifi bir kunda yaratilgan.', 'The classification was created in a single day.', 0]] },

    { t: ['Kimyoviy elementlarning tabiiy oilalari', 'Natural families of chemical elements'], q: ['Nima uchun bir guruhdagi elementlar o\'xshash xossalarga ega?', 'Why do elements in the same group have similar properties?'],
      i: ["O'xshash xossali elementlar bir oilaga (guruhga) kiradi, chunki ularning tashqi qavatidagi elektronlar soni bir xil.", 'Elements with similar properties form a family (group) because they have the same number of outer electrons.'],
      p: [["<b>Ishqoriy metallar</b> (1-guruh: Li, Na, K) — juda faol, suv bilan shiddatli reaksiyaga kirishadi.", '<b>Alkali metals</b> (group 1: Li, Na, K) — very reactive, react vigorously with water.'], ["<b>Ishqoriy-yer metallari</b> (2-guruh: Mg, Ca) — faol, lekin 1-guruhdan kamroq.", '<b>Alkaline earth metals</b> (group 2: Mg, Ca) — reactive, but less than group 1.'], ["<b>Galogenlar</b> (7-guruh: F, Cl, Br, I) — faol nometallar, metallar bilan tuz hosil qiladi.", '<b>Halogens</b> (group 7: F, Cl, Br, I) — reactive non-metals that form salts with metals.'], ["<b>Inert gazlar</b> (8-guruh: He, Ne, Ar) — deyarli reaksiyaga kirishmaydi.", '<b>Noble gases</b> (group 8: He, Ne, Ar) — almost unreactive.']],
      k: [['Galogen', '7-guruh elementi; "tuz hosil qiluvchi"', 'Halogen', 'A group 7 element; "salt former"'], ['Ishqoriy metall', '1-guruh faol metali', 'Alkali metal', 'A reactive group 1 metal']],
      z: [['1-guruh elementlari ishqoriy metallar deyiladi.', 'Group 1 elements are alkali metals.', 1], ['Kalsiy 1-guruh elementi.', 'Calcium is in group 1.', 0], ['7-guruh elementlari galogenlar.', 'Group 7 elements are halogens.', 1], ['Neon 8-guruh elementi.', 'Neon is a group 8 element.', 1]] },

    { t: ['Kimyoviy elementlar davriy jadvali', 'The periodic table of chemical elements'], q: ['Davriy jadval qanday tuzilgan?', 'How is the periodic table organised?'],
      i: ["Davriy jadvalda elementlar yadro zaryadi ortib borishi tartibida joylashgan. Gorizontal qatorlar — davrlar, vertikal ustunlar — guruhlar.", 'In the periodic table, elements are arranged by increasing nuclear charge. Rows are periods; columns are groups.'],
      p: [["<b>Davr</b> raqami atomdagi elektron qavatlar sonini bildiradi (Na — 3-davr, 3 qavat).", 'The <b>period</b> number equals the number of electron shells (Na — period 3, 3 shells).'], ["<b>Guruh</b> raqami (A-guruhlarda) tashqi qavat elektronlari sonini bildiradi (Cl — 7-guruh, 7 ta tashqi elektron).", 'The <b>group</b> number (main groups) equals the outer electrons (Cl — group 7, 7 outer electrons).'], ["Davr bo'ylab chapdan o'ngga metall xossalari kamayadi, nometall xossalari ortadi.", 'Across a period, metallic character decreases and non-metallic character increases.'], ["Guruhda yuqoridan pastga metall xossalari ortadi.", 'Down a group, metallic character increases.']],
      k: [['Davr', 'Jadvalning gorizontal qatori', 'Period', 'A horizontal row'], ['Guruh', 'Jadvalning vertikal ustuni', 'Group', 'A vertical column']],
      f: ['Mendeleyev galliy, skandiy va germaniy kashf etilishidan oldin ularning xossalarini aniq bashorat qilgan.', 'Mendeleev predicted the properties of gallium, scandium and germanium before they were discovered.'],
      z: [['Davr raqami elektron qavatlar sonini bildiradi.', 'The period number gives the number of shells.', 1], ['Guruhlar — gorizontal qatorlar.', 'Groups are horizontal rows.', 0], ['Cl ning tashqi qavatida 7 ta elektron bor.', 'Cl has 7 outer electrons.', 1], ['Elementlar yadro zaryadi ortib borishi tartibida joylashgan.', 'Elements are ordered by increasing nuclear charge.', 1]] },

    { t: ['Havo va uning tarkibi', 'Air and its composition'], q: ['Ko\'rinmas, ammo hayot uchun zarur aralashma — havo nimadan iborat?', 'What is air — the invisible yet essential mixture — made of?'],
      i: ['Havo — Yer atmosferasini tashkil etuvchi gazlar aralashmasi.', 'Air is the mixture of gases that makes up Earth’s atmosphere.'],
      p: [["Azot (N₂) ≈ 78%, kislorod (O₂) ≈ 21%, argon (Ar) ≈ 0,93%, karbonat angidrid (CO₂) ≈ 0,04%, shuningdek suv bug'i.", 'Nitrogen (N₂) ≈ 78%, oxygen (O₂) ≈ 21%, argon (Ar) ≈ 0.93%, carbon dioxide (CO₂) ≈ 0.04%, plus water vapour.'], ["Havo — aralashma: uning tarkibiy qismlari o'z xossalarini saqlaydi va fizik usulda ajratilishi mumkin (suyuq havoni distillash).", 'Air is a mixture: its parts keep their properties and can be separated physically (distilling liquid air).'], ["Kislorod nafas olish va yonish uchun, azot o'simliklar oziqlanishi uchun muhim.", 'Oxygen is needed for breathing and burning; nitrogen for plant nutrition.'], ["Atmosfera Yerni ultrabinafsha nurlardan himoya qiladi va issiqlikni saqlaydi.", 'The atmosphere protects Earth from UV rays and keeps it warm.']],
      k: [['Atmosfera', 'Yerni o\'rab turgan gaz qobig\'i', 'Atmosphere', 'The gas layer around Earth']],
      z: [['Havoda eng ko\'p azot bor.', 'Air contains most nitrogen.', 1], ['Havodagi kislorod ulushi ≈ 21%.', 'Air is ≈ 21% oxygen.', 1], ['Havo — sof modda.', 'Air is a pure substance.', 0], ['Havo tarkibida argon bor.', 'Air contains argon.', 1]] },

    { t: ['Havoning ifloslanishiga ta\'sir etuvchi omillar', 'Factors affecting air pollution'], q: ['Havoni nima ifloslantiradi?', 'What pollutes the air?'],
      i: ['Toza havo — sog\'lom hayot garovi! Havoning ifloslanishi — unga zararli gazlar, chang va boshqa zarrachalarning tushishi.', 'Clean air is a guarantee of a healthy life! Air pollution is the entry of harmful gases, dust and particles.'],
      p: [["Avtomobil transporti: CO, NO₂; zavod va issiqlik elektr stansiyalari (ko'mir, gaz): SO₂, CO₂, chang.", 'Road transport: CO, NO₂; factories and power stations (coal, gas): SO₂, CO₂, dust.'], ["Chiqindilarni yoqish: CO, dioksinlar; tabiiy omillar: vulqonlar, chang bo'ronlari, o'rmon yong'inlari.", 'Burning waste: CO, dioxins; natural factors: volcanoes, dust storms, forest fires.'], ["Ifloslangan havo astma, allergiya, yurak kasalliklariga sabab bo'ladi va kislotali yomg'ir, smog hosil qiladi.", 'Polluted air causes asthma, allergies, heart disease, acid rain and smog.'], ["Himoya: daraxt ekish, filtrlar, jamoat transporti, chiqindilarni yoqmaslik.", 'Protection: planting trees, filters, public transport, not burning waste.']],
      k: [['Smog', 'Tutun va tumanning zaharli aralashmasi', 'Smog', 'A toxic mix of smoke and fog']],
      z: [['Havo ifloslanishi faqat shaharlarda kuzatiladi.', 'Air pollution occurs only in cities.', 0], ['Karbonat angidrid havoda tabiiy holda bor.', 'Carbon dioxide is naturally present in air.', 1], ['Chang zarrachalari ham havoni ifloslantiradi.', 'Dust also pollutes air.', 1], ['Chiqindilarni yoqish havoni ifloslantiradi.', 'Burning waste pollutes air.', 1]] },

    { t: ['Kislorod va uning umumiy tavsifi', 'Oxygen and its general description'], q: ['Kislorod tabiatda qayerda uchraydi?', 'Where is oxygen found in nature?'],
      i: ['Kislorod — hayot uchun zarur element va tabiatda eng keng tarqalgan elementlardan biri.', 'Oxygen is an element essential for life and one of the most widespread in nature.'],
      p: [["Belgisi <b>O</b>, Z = 8, Aᵣ = 16, 2-davr, 6-guruh; elektronlari 2, 6.", 'Symbol <b>O</b>, Z = 8, Aᵣ = 16, period 2, group 6; electrons 2, 6.'], ["Erkin holda: havoda O₂ (≈ 21%) va ozon O₃.", 'Free state: O₂ in air (≈ 21%) and ozone O₃.'], ["Birikmalarda: suv (massasining ≈ 89%), qum (SiO₂), tog' jinslari, tirik organizmlar.", 'In compounds: water (≈ 89% by mass), sand (SiO₂), rocks, living things.'], ["Kislorod Yer po'stida eng ko'p tarqalgan element (≈ 49% massa).", 'Oxygen is the most abundant element in Earth’s crust (≈ 49% by mass).']],
      k: [['Kislorod', 'O, Z = 8; hayot uchun zarur element', 'Oxygen', 'O, Z = 8; an element essential for life']],
      f: ['Kislorodni 1770-yillarda K. Sheele va J. Pristli bir-biridan mustaqil ravishda kashf qilgan.', 'Oxygen was discovered independently by C. Scheele and J. Priestley in the 1770s.'],
      z: [['Kislorodning kimyoviy belgisi O.', 'Oxygen’s symbol is O.', 1], ['Kislorod faqat birikmalarda uchraydi.', 'Oxygen occurs only in compounds.', 0], ['Suv molekulasida kislorod bor.', 'Water molecules contain oxygen.', 1], ['Kislorod tabiatda keng tarqalgan.', 'Oxygen is widespread in nature.', 1]] },

    { t: ['Kislorodning fizik va kimyoviy xossalari', 'Physical and chemical properties of oxygen'], q: ['Kislorod qanday xossalarga ega?', 'What properties does oxygen have?'],
      i: ['Kislorod — hayot va o\'zgarishlar manbai! U ko\'plab moddalar bilan reaksiyaga kirishib, oksidlar hosil qiladi.', 'Oxygen is a source of life and change! It reacts with many substances to form oxides.'],
      p: [["<b>Fizik xossalari</b>: rangsiz, hidsiz, ta'msiz gaz; havodan biroz og'ir; suvda kam eriydi; −183 °C da suyuqlanadi (suyuq kislorod — havorang).", '<b>Physical</b>: colourless, odourless, tasteless gas; slightly heavier than air; slightly soluble in water; liquefies at −183 °C (pale blue liquid).'], ["<b>Kimyoviy xossalari</b>: metallar va nometallar bilan reaksiyaga kirishib oksidlar hosil qiladi.", '<b>Chemical</b>: reacts with metals and non-metals forming oxides.'], ["Kislorod yonishni qo'llab-quvvatlaydi, lekin o'zi yonmaydi — cho'g'langan cho'p unda alangalanadi.", 'Oxygen supports burning but does not burn — a glowing splint relights in it.'], ["Laboratoriyada KMnO₄ ni qizdirib olinadi.", 'In the lab it is made by heating KMnO₄.']],
      e: ['2Mg + O₂ → 2MgO', 'C + O₂ → CO₂', '2KMnO₄ → K₂MnO₄ + MnO₂ + O₂↑'],
      z: [['Kislorod rangsiz gaz.', 'Oxygen is a colourless gas.', 1], ['Kislorod magniy bilan reaksiyaga kirishadi.', 'Oxygen reacts with magnesium.', 1], ['Kislorod suvda juda yaxshi eriydi.', 'Oxygen dissolves very well in water.', 0], ["Cho'g'langan cho'p kislorodda alangalanadi.", 'A glowing splint relights in oxygen.', 1]] },

    { t: ['Kislorodning qo\'llanilishi', 'Uses of oxygen'], q: ['Kislorod inson hayotining qaysi sohalarida ishlatiladi?', 'Where is oxygen used in human life?'],
      i: ['Kislorodning o\'ziga xos xossalari uni hayot, tabiatni muhofaza qilish va sanoat uchun juda muhim qiladi.', 'Oxygen’s unique properties make it vital for life, environmental protection and industry.'],
      p: [["<b>Tibbiyot</b>: nafas olishi qiyin bemorlarga kislorod beriladi (kislorod yostiqlari, ballonlar).", '<b>Medicine</b>: oxygen helps patients who struggle to breathe (masks, cylinders).'], ["<b>Metallurgiya</b>: po'lat ishlab chiqarish; metallarni kesish va payvandlash.", '<b>Metallurgy</b>: steelmaking; cutting and welding metals.'], ["<b>Raketa texnikasi</b>: suyuq kislorod yoqilg'ini oksidlovchi.", '<b>Rocketry</b>: liquid oxygen is the fuel oxidiser.'], ["<b>Ekologiya</b>: oqova suvlarni tozalash; g'avvoslar va uchuvchilar uchun nafas olish aralashmalari.", '<b>Ecology</b>: treating waste water; breathing mixtures for divers and pilots.']],
      k: [['Oksidlovchi', 'Boshqa moddani oksidlaydigan modda', 'Oxidiser', 'A substance that oxidises another']],
      z: [['Kislorod tibbiyotda nafas olishga yordam beradi.', 'Oxygen helps breathing in medicine.', 1], ['Suyuq kislorod raketalarda oksidlovchi.', 'Liquid oxygen is a rocket oxidiser.', 1], ['Kislorod metall payvandlashda ishlatiladi.', 'Oxygen is used in welding.', 1], ['Kislorod faqat tirik organizmlar uchun muhim.', 'Oxygen matters only for living things.', 0]] },

    { t: ['Yonish jarayoni', 'The combustion process'], q: ['Yonish sodir bo\'lishi uchun nima kerak?', 'What is needed for combustion?'],
      i: ['Issiqlik, yorug\'lik va yangi moddalar! Yonish — moddalarning kislorod bilan tez birikishi; bunda issiqlik, yorug\'lik va oksidlar hosil bo\'ladi.', 'Heat, light and new substances! Combustion is a fast reaction with oxygen that produces heat, light and oxides.'],
      p: [["Yonish uchun uch shart: <b>yonuvchi modda</b>, <b>kislorod</b> va <b>alangalanish harorati</b>.", 'Three conditions: <b>fuel</b>, <b>oxygen</b> and the <b>ignition temperature</b>.'], ["Har bir moddaning o'z alangalanish harorati bor: gugurt boshi ≈ 200 °C, qog'oz ≈ 230 °C.", 'Each substance has its own ignition temperature: match head ≈ 200 °C, paper ≈ 230 °C.'], ["To'liq yonishda CO₂ va H₂O, chala yonishda zaharli CO va qurum hosil bo'ladi.", 'Complete combustion gives CO₂ and H₂O; incomplete combustion gives toxic CO and soot.'], ["Yonish davomida kislorod sarflanadi.", 'Oxygen is consumed during combustion.']],
      e: ['CH₄ + 2O₂ → CO₂ + 2H₂O + Q'],
      k: [['Alangalanish harorati', 'Modda yona boshlaydigan eng past harorat', 'Ignition temperature', 'The lowest temperature at which a substance starts burning'], ['Chala yonish', 'Kislorod yetishmaganda CO va qurum hosil bo\'lishi', 'Incomplete combustion', 'Burning with too little oxygen, giving CO and soot']],
      z: [['Yonish uchun faqat yonuvchi modda yetarli.', 'Only fuel is needed for combustion.', 0], ['Yonishda issiqlik va yorug\'lik ajraladi.', 'Combustion releases heat and light.', 1], ['Yonish natijasida oksidlar hosil bo\'ladi.', 'Combustion forms oxides.', 1], ['Yonishda kislorod sarflanmaydi.', 'Oxygen is not used up in combustion.', 0]] },

    { t: ["Yoqilg'ilar", 'Fuels'], q: ["Kundalik hayotda yoqilg'i nima uchun kerak?", 'Why do we need fuels in daily life?'],
      i: ["Yoqilg'i — yonganda ko'p issiqlik ajratadigan modda. U uylarni isitish, ovqat pishirish, transport va elektr ishlab chiqarishda ishlatiladi.", 'A fuel releases a lot of heat when it burns. Fuels heat homes, cook food, move vehicles and generate electricity.'],
      p: [["Qattiq: o'tin, ko'mir; suyuq: benzin, dizel, kerosin; gazsimon: tabiiy gaz (metan), propan.", 'Solid: firewood, coal; liquid: petrol, diesel, kerosene; gas: natural gas (methane), propane.'], ["Tabiiy gaz (metan) rangsiz va hidsiz; xavfsizlik uchun unga o'tkir hidli modda qo'shiladi. U toza alanga bilan yonadi.", 'Natural gas (methane) is colourless and odourless; a smelly substance is added for safety. It burns with a clean flame.'], ["Qazilma yoqilg'ilar yonganda CO₂ (issiqxona effekti) va SO₂ (kislotali yomg'ir) ajraladi.", 'Burning fossil fuels releases CO₂ (greenhouse effect) and SO₂ (acid rain).'], ["Muqobil energiya: quyosh, shamol, vodorod, biogaz.", 'Alternatives: solar, wind, hydrogen, biogas.']],
      k: [["Qazilma yoqilg'i", "Ko'mir, neft, gaz — qadimiy organizmlar qoldig'i", 'Fossil fuel', 'Coal, oil, gas — remains of ancient organisms']],
      f: ["O'zbekiston tabiiy gaz zaxiralariga boy — Sho'rtan, Muborak, Gazli konlari mashhur.", 'Uzbekistan is rich in natural gas — Shurtan, Mubarek and Gazli fields are well known.'],
      z: [['Tabiiy gaz o\'z holida rangsiz va hidsiz.', 'Natural gas itself is colourless and odourless.', 1], ["O'tin — suyuq yoqilg'i.", 'Firewood is a liquid fuel.', 0], ['Metan toza alanga bilan yonadi.', 'Methane burns with a clean flame.', 1], ["Qazilma yoqilg'ilar CO₂ chiqaradi.", 'Fossil fuels release CO₂.', 1]] },

    { t: ['Amaliy ish: alanga tuzilishi va moddalarning kislorodda yonishi', 'Practical: flame structure and combustion of substances in oxygen'], q: ['Alanganing qaysi zonasi eng issiq va moddalar kislorodda qanday yonadi?', 'Which flame zone is hottest, and how do substances burn in oxygen?'],
      i: ['Bu darsda alanga tuzilishini o\'rganamiz va moddalarning havoda hamda kislorodda yonishini taqqoslaymiz.', 'In this lesson we study flame structure and compare burning in air and in oxygen.'],
      p: [["Alanga uch zonadan iborat: <b>ichki</b> (eng sovuq), <b>o'rta</b> (sariq, yorqin — chala yonish), <b>tashqi</b> (eng issiq — to'liq yonish).", 'A flame has three zones: <b>inner</b> (coolest), <b>middle</b> (yellow, bright — incomplete combustion), <b>outer</b> (hottest — complete combustion).'], ["Magniy ko'zni qamashtiruvchi oq alanga bilan yonib, oq kukun MgO hosil qiladi.", 'Magnesium burns with a dazzling white flame, forming white MgO powder.'], ["Oltingugurt havoda zaif, kislorodda yorqin ko'k-binafsha alanga bilan yonadi (SO₂).", 'Sulfur burns weakly in air but bright blue-violet in oxygen (SO₂).'], ["Ko'mir kislorodda yorqin cho'g'lanib yonadi va CO₂ hosil qiladi. Kislorodda yonish havodagidan shiddatliroq.", 'Charcoal glows brightly in oxygen, forming CO₂. Burning is more vigorous in oxygen than in air.']],
      e: ['2Mg + O₂ → 2MgO', 'S + O₂ → SO₂', 'C + O₂ → CO₂'],
      z: [['Alanganing tashqi zonasi eng issiq.', 'The outer flame zone is hottest.', 1], ['Sariq zonada yonmagan gazlar bor.', 'The yellow zone contains unburnt gases.', 1], ['Moddalar kislorodda havodagidan kuchliroq yonadi.', 'Substances burn more strongly in oxygen than in air.', 1], ['Magniy qizil alanga bilan yonadi.', 'Magnesium burns with a red flame.', 0]] },

    { t: ['Ozon', 'Ozone'], q: ['Ozon qatlami nima uchun hayot uchun muhim?', 'Why is the ozone layer essential for life?'],
      i: ["Ozon (O₃) — kislorodning allotropik shakli, uchta kislorod atomidan iborat. U asosan stratosferada joylashib, himoya qatlamini hosil qiladi.", 'Ozone (O₃) is an allotrope of oxygen with three oxygen atoms. Mostly found in the stratosphere, it forms a protective layer.'],
      p: [["Ozon — o'tkir hidli, havorang gaz; chaqmoq va ultrabinafsha nur ta'sirida kisloroddan hosil bo'ladi.", 'Ozone is a pale blue gas with a sharp smell, formed from oxygen by lightning and UV light.'], ["Ozon qatlami (15–35 km balandlikda, stratosferada) Quyoshning zararli <b>ultrabinafsha (UB)</b> nurlarini yutadi.", 'The ozone layer (15–35 km up, in the stratosphere) absorbs the Sun’s harmful <b>ultraviolet (UV)</b> rays.'], ["Pastki atmosferadagi (troposferadagi) ozon esa inson sog'lig'iga zararli.", 'Ozone in the lower atmosphere (troposphere) is harmful to health.'], ["Freonlar (xlorftoruglerodlar) ozon qatlamini yemiradi; ular xalqaro kelishuv bilan taqiqlangan.", 'CFCs (freons) destroy the ozone layer and are banned by international agreement.']],
      e: ['3O₂ → 2O₃ (UB nur, chaqmoq / UV light, lightning)'],
      k: [['Ozon', 'O₃ — kislorodning allotropi', 'Ozone', 'O₃ — an allotrope of oxygen'], ['Stratosfera', 'Atmosferaning 10–50 km dagi qatlami', 'Stratosphere', 'The atmospheric layer at 10–50 km']],
      z: [['Ozon formulasi O₃.', 'Ozone’s formula is O₃.', 1], ['Ozon qatlami troposferada joylashgan.', 'The ozone layer is in the troposphere.', 0], ['UB nurlar tirik organizmlarga zararli.', 'UV rays are harmful to living things.', 1], ['Pastki atmosferadagi ozon sog\'liq uchun zararli.', 'Low-level ozone is harmful to health.', 1]] },

    { t: ['Kislorodning biologik ahamiyati', 'Biological importance of oxygen'], q: ['Tirik organizmlar uchun kislorod nima uchun zarur?', 'Why do living things need oxygen?'],
      i: ['Hayot kislorodga muhtoj! U barcha tirik organizmlarning hayot faoliyati uchun zarur.', 'Life needs oxygen! It is essential for the life processes of all living organisms.'],
      p: [["<b>Nafas olish</b>: hujayralarda oziq moddalar kislorod yordamida parchalanib, energiya ajraladi.", '<b>Respiration</b>: in cells, food is broken down with oxygen to release energy.'], ["<b>Fotosintez</b>: o'simliklar kunduzi CO₂ ni yutib, kislorod ajratadi; nafas olishni esa kecha-kunduz davom ettiradi.", '<b>Photosynthesis</b>: plants absorb CO₂ and release oxygen by day; they respire day and night.'], ["Baliqlar suvda erigan kislorod bilan nafas oladi.", 'Fish breathe oxygen dissolved in water.'], ["Kislorod chirish va parchalanish jarayonlarida ishtirok etadi; tabiatda kislorod miqdori aylanish tufayli taxminan doimiy saqlanadi.", 'Oxygen takes part in decay; its amount in nature stays roughly constant thanks to cycling.']],
      e: ['6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ (yorug\'lik / light)'],
      z: [['Kislorod barcha tirik organizmlar uchun zarur.', 'Oxygen is essential for all living organisms.', 1], ["O'simliklar faqat kechasi nafas oladi.", 'Plants breathe only at night.', 0], ['Baliqlar suvda erigan kislorod bilan nafas oladi.', 'Fish breathe dissolved oxygen.', 1], ['Kislorod moddalar parchalanishida ishtirok etadi.', 'Oxygen takes part in decomposition.', 1]] },

    { t: ['Oksidlar', 'Oxides'], q: ['Oksidlar qanday moddalar?', 'What are oxides?'],
      i: ["Oksidlar — ikki elementdan iborat, biri kislorod bo'lgan birikmalar. Ular havoda, suvda, tog' jinslarida va tirik organizmlarda keng tarqalgan.", 'Oxides are compounds of two elements, one of which is oxygen. They are found in air, water, rocks and living things.'],
      p: [["Umumiy formula: <b>EₓOᵧ</b>. Misollar: CaO, CO₂, H₂O, SO₂, Al₂O₃, Fe₂O₃.", 'General formula: <b>EₓOᵧ</b>. Examples: CaO, CO₂, H₂O, SO₂, Al₂O₃, Fe₂O₃.'], ["Suv (H₂O) ham oksid — vodorod oksidi.", 'Water (H₂O) is an oxide too — hydrogen oxide.'], ["Oksidlar qattiq (CaO, SiO₂), suyuq (H₂O) yoki gaz (CO₂, SO₂) bo'lishi mumkin.", 'Oxides can be solid (CaO, SiO₂), liquid (H₂O) or gas (CO₂, SO₂).'], ["NaCl, HCl, NaOH oksid emas: NaCl va HCl da kislorod yo'q, NaOH esa uch elementdan iborat.", 'NaCl, HCl and NaOH are not oxides: the first two have no oxygen and NaOH has three elements.']],
      k: [['Oksid', 'Ikki elementli, biri kislorod bo\'lgan birikma', 'Oxide', 'A two-element compound containing oxygen']],
      z: [['Oksidlar ikki elementdan iborat.', 'Oxides consist of two elements.', 1], ['Suv oksid hisoblanadi.', 'Water is an oxide.', 1], ['CO₂ oksid emas.', 'CO₂ is not an oxide.', 0], ['Oksidlar qattiq, suyuq yoki gaz bo\'lishi mumkin.', 'Oxides can be solid, liquid or gas.', 1]] },

    { t: ['Oksidlarning turlari', 'Types of oxides'], q: ['Oksidlar kimyoviy xossalariga ko\'ra qanday turlarga bo\'linadi?', 'How are oxides classified by chemical properties?'],
      i: ['Oksidlar to\'rt turga bo\'linadi: asosli, kislotali, amfoter va neytral (befarq).', 'Oxides fall into four types: basic, acidic, amphoteric and neutral.'],
      p: [["<b>Asosli oksidlar</b> — faol metallar oksidlari (Na₂O, CaO, MgO); kislotalar bilan tuz hosil qiladi.", '<b>Basic oxides</b> — oxides of active metals (Na₂O, CaO, MgO); react with acids to form salts.'], ["<b>Kislotali oksidlar</b> — nometallar oksidlari (CO₂, SO₂, SO₃, P₂O₅); suv bilan kislota hosil qiladi.", '<b>Acidic oxides</b> — oxides of non-metals (CO₂, SO₂, SO₃, P₂O₅); react with water to form acids.'], ["<b>Amfoter oksidlar</b> (Al₂O₃, ZnO) — ham kislota, ham asos bilan reaksiyaga kirishadi.", '<b>Amphoteric oxides</b> (Al₂O₃, ZnO) react with both acids and bases.'], ["<b>Neytral oksidlar</b> (CO, NO, N₂O) — odatda kislota ham, asos ham bilan reaksiyaga kirishmaydi.", '<b>Neutral oxides</b> (CO, NO, N₂O) usually react with neither.']],
      e: ['CaO + H₂O → Ca(OH)₂', 'SO₃ + H₂O → H₂SO₄'],
      z: [['Barcha metall oksidlari asosli oksid.', 'All metal oxides are basic.', 0, ['Al₂O₃ va ZnO — amfoter.', 'Al₂O₃ and ZnO are amphoteric.']], ['Ba\'zi kislotali oksidlar suv bilan kislota hosil qiladi.', 'Some acidic oxides form acids with water.', 1], ['Amfoter oksidlar ham kislota, ham asos bilan reaksiyaga kirishadi.', 'Amphoteric oxides react with both acids and bases.', 1], ['CaO — neytral oksid.', 'CaO is a neutral oxide.', 0]] },

    { t: ['Eng muhim oksidlar', 'The most important oxides'], q: ['Kundalik hayotda qaysi oksidlar muhim?', 'Which oxides matter in daily life?'],
      i: ['Bu darsda eng muhim oksidlar: CO₂, CaO, SiO₂, Al₂O₃, Fe₂O₃ va CO bilan tanishamiz.', 'We meet the most important oxides: CO₂, CaO, SiO₂, Al₂O₃, Fe₂O₃ and CO.'],
      p: [["<b>CO₂</b> — karbonat angidrid: fotosintez uchun zarur, gazli ichimliklarda, o't o'chirgichlarda.", '<b>CO₂</b> — carbon dioxide: needed for photosynthesis; in fizzy drinks and fire extinguishers.'], ["<b>CaO</b> — so'ndirilmagan ohak: suv bilan Ca(OH)₂ (so'ndirilgan ohak) hosil qiladi, qurilishda ishlatiladi.", '<b>CaO</b> — quicklime: with water forms Ca(OH)₂ (slaked lime), used in building.'], ["<b>SiO₂</b> — qum va kvars; shisha tayyorlashda. <b>Al₂O₃</b> — amfoter, alyuminiy rudasi (boksit). <b>Fe₂O₃</b> — temir rudasi, zang.", '<b>SiO₂</b> — sand and quartz; for glass. <b>Al₂O₃</b> — amphoteric, aluminium ore (bauxite). <b>Fe₂O₃</b> — iron ore, rust.'], ["<b>CO</b> — is gazi: rangsiz, hidsiz va juda zaharli! Pechlardan chala yonish natijasida chiqadi.", '<b>CO</b> — carbon monoxide: colourless, odourless and highly toxic! Produced by incomplete burning in stoves.']],
      k: [['Is gazi (CO)', 'Zaharli, hidsiz gaz', 'Carbon monoxide (CO)', 'A toxic, odourless gas']],
      f: ['Gaz pechlari bor xonani muntazam shamollatish is gazidan zaharlanishning oldini oladi.', 'Airing rooms with gas heaters regularly prevents carbon monoxide poisoning.'],
      z: [['CaO suv bilan reaksiyaga kirishmaydi.', 'CaO does not react with water.', 0], ['SiO₂ qum va tog\' jinslarida uchraydi.', 'SiO₂ is found in sand and rocks.', 1], ['Al₂O₃ — amfoter oksid.', 'Al₂O₃ is amphoteric.', 1], ['CO zararsiz gaz.', 'CO is a harmless gas.', 0]] },

    { t: ['Vodorod, uning izotoplari va ahamiyati', 'Hydrogen, its isotopes and their importance'], q: ['Vodorod qanday element?', 'What kind of element is hydrogen?'],
      i: ['Vodorod — eng yengil kimyoviy element va koinotda eng ko\'p tarqalgan element.', 'Hydrogen is the lightest element and the most abundant in the universe.'],
      p: [["Belgisi <b>H</b>, Z = 1, Aᵣ = 1; atomida 1 proton va 1 elektron.", 'Symbol <b>H</b>, Z = 1, Aᵣ = 1; one proton and one electron.'], ["Izotoplari: <b>protiy</b> ¹H (eng keng tarqalgan), <b>deyteriy</b> ²H (D), <b>tritiy</b> ³H (T, radioaktiv).", 'Isotopes: <b>protium</b> ¹H (most common), <b>deuterium</b> ²H (D), <b>tritium</b> ³H (T, radioactive).'], ["Tabiatda asosan birikmalar tarkibida: suv, organik moddalar, tabiiy gaz.", 'In nature mainly in compounds: water, organic matter, natural gas.'], ["Quyosh va yulduzlar asosan vodoroddan iborat; ularda vodorod geliyga aylanib, energiya ajraladi.", 'The Sun and stars are mostly hydrogen, which fuses into helium releasing energy.']],
      k: [['Deyteriy', 'Vodorodning ²H izotopi', 'Deuterium', 'The ²H isotope of hydrogen'], ['Tritiy', 'Vodorodning radioaktiv ³H izotopi', 'Tritium', 'The radioactive ³H isotope']],
      z: [['Vodorod eng yengil element.', 'Hydrogen is the lightest element.', 1], ['Deyteriy tabiatda juda keng tarqalgan.', 'Deuterium is very widespread in nature.', 0], ['Vodorodning 3 ta izotopi bor.', 'Hydrogen has 3 isotopes.', 1], ['Vodorod atomida 1 ta proton bor.', 'A hydrogen atom has 1 proton.', 1]] },

    { t: ['Vodorodning olinishi', 'Obtaining hydrogen'], q: ['Vodorod laboratoriya va sanoatda qanday olinadi?', 'How is hydrogen obtained in the lab and in industry?'],
      i: ['Vodorod tabiatda asosan birikmalar tarkibida uchraydi. U turli usullar bilan olinadi.', 'Hydrogen occurs mainly in compounds and can be obtained in several ways.'],
      p: [["<b>Laboratoriyada</b>: faol metallarni (Zn, Fe) suyultirilgan kislota bilan reaksiyaga kiritib.", '<b>In the lab</b>: reacting active metals (Zn, Fe) with dilute acid.'], ["<b>Sanoatda</b>: tabiiy gazni (metanni) suv bug'i bilan reaksiyaga kiritib.", '<b>In industry</b>: reacting natural gas (methane) with steam.'], ["<b>Suv elektrolizi</b>: elektr toki suvni vodorod va kislorodga ajratadi — kelajakning \"yashil vodorodi\".", '<b>Electrolysis of water</b>: current splits water into hydrogen and oxygen — the "green hydrogen" of the future.'], ["Vodorod havodan yengil, shuning uchun og'zi pastga qaratilgan idishga yig'iladi.", 'Hydrogen is lighter than air, so it is collected in an upside-down container.']],
      e: ['Zn + 2HCl → ZnCl₂ + H₂↑', 'CH₄ + H₂O → CO + 3H₂', '2H₂O → 2H₂↑ + O₂↑'],
      k: [['Elektroliz', 'Elektr toki yordamida moddani parchalash', 'Electrolysis', 'Breaking down a substance with electric current']],
      z: [['Vodorod tabiatda asosan birikmalarda uchraydi.', 'Hydrogen occurs mainly in compounds.', 1], ['Rux suyultirilgan HCl bilan vodorod hosil qiladi.', 'Zinc and dilute HCl form hydrogen.', 1], ['Suv elektrolizida faqat vodorod hosil bo\'ladi.', 'Only hydrogen forms in water electrolysis.', 0], ['Sanoatda vodorod metandan olinadi.', 'Industry makes hydrogen from methane.', 1]] },

    { t: ['Vodorodning xossalari', 'Properties of hydrogen'], q: ['Vodorod qanday fizik va kimyoviy xossalarga ega?', 'What are hydrogen’s physical and chemical properties?'],
      i: ['Vodorod rangsiz, hidsiz va ta\'msiz gaz. U havodan 14–15 marta yengil va yonuvchi gaz.', 'Hydrogen is a colourless, odourless, tasteless gas, 14–15 times lighter than air, and flammable.'],
      p: [["Fizik: eng yengil gaz, suvda kam eriydi, −253 °C da suyuqlanadi.", 'Physical: lightest gas, slightly soluble in water, liquefies at −253 °C.'], ["Kislorodda yonib, suv hosil qiladi; vodorod va havo aralashmasi portlovchi (\"qaldiroq gaz\").", 'Burns in oxygen to form water; hydrogen–air mixtures are explosive ("oxyhydrogen").'], ["Ba'zi metall oksidlarini metallgacha qaytaradi: CuO + H₂ → Cu + H₂O.", 'It reduces some metal oxides to metals: CuO + H₂ → Cu + H₂O.'], ["Yonish mahsuloti faqat suv — shuning uchun vodorod ekologik toza yoqilg'i.", 'Its only combustion product is water — a clean fuel.']],
      e: ['2H₂ + O₂ → 2H₂O', 'CuO + H₂ → Cu + H₂O'],
      k: [['Qaytarish', 'Oksiddan kislorodni tortib olish', 'Reduction', 'Removing oxygen from an oxide']],
      z: [['Vodorod rangsiz, hidsiz, ta\'msiz gaz.', 'Hydrogen is colourless, odourless and tasteless.', 1], ['Vodorod havodan yengil.', 'Hydrogen is lighter than air.', 1], ['Vodorod suvda juda yaxshi eriydi.', 'Hydrogen dissolves very well in water.', 0], ['Vodorod yonganda suv hosil bo\'ladi.', 'Burning hydrogen forms water.', 1]] },

    { t: ['Kislotalar', 'Acids'], q: ['Kislotalar qanday moddalar va ularni qanday aniqlaymiz?', 'What are acids and how do we identify them?'],
      i: ["Kislotalar — tarkibida vodorod atomlari va kislota qoldig'i bo'lgan murakkab moddalar. Ular kundalik hayotimizda muhim o'rin tutadi.", 'Acids are compounds containing hydrogen atoms and an acid residue. They play an important role in everyday life.'],
      p: [["Kislotalar suvli eritmada <b>H⁺</b> ionlarini hosil qiladi.", 'Acids form <b>H⁺</b> ions in aqueous solution.'], ["Misollar: HCl (xlorid), H₂SO₄ (sulfat), HNO₃ (nitrat), H₃PO₄ (fosfat), H₂CO₃ (karbonat) kislotalar.", 'Examples: HCl (hydrochloric), H₂SO₄ (sulfuric), HNO₃ (nitric), H₃PO₄ (phosphoric), H₂CO₃ (carbonic).'], ["Indikatorlar: ko'k lakmus qog'ozi kislotada <b>qizaradi</b>, metil zarg'aldog'i qizil-pushti rangga kiradi.", 'Indicators: blue litmus turns <b>red</b> in acid; methyl orange turns red-pink.'], ["Kislotani ta'midan aniqlash mumkin emas — bu xavfli!", 'Never identify an acid by taste — it is dangerous!']],
      k: [["Kislota qoldig'i", 'Kislota tarkibidagi vodoroddan boshqa qism', 'Acid residue', 'The part of an acid other than hydrogen'], ['Lakmus', 'Kislotada qizil, ishqorda ko\'k bo\'luvchi indikator', 'Litmus', 'An indicator: red in acid, blue in alkali']],
      z: [['Kislotalar suvda H⁺ ionlarini hosil qiladi.', 'Acids form H⁺ ions in water.', 1], ['Kislotalar suvda OH⁻ ionlarini hosil qiladi.', 'Acids form OH⁻ ions in water.', 0], ["Ko'k lakmus kislotada qizaradi.", 'Blue litmus turns red in acid.', 1], ['Kislotani har doim ta\'midan aniqlash mumkin.', 'Acids can always be identified by taste.', 0]] },

    { t: ['Kislotalarning turlari', 'Types of acids'], q: ['Kislotalar qanday guruhlarga bo\'linadi?', 'How are acids grouped?'],
      i: ["Kislotalar vodorod atomlari soni, kislota qoldig'ining tarkibi va suvda dissotsilanish darajasiga ko'ra tasniflanadi.", 'Acids are classified by number of hydrogen atoms, composition of the residue and degree of dissociation.'],
      p: [["<b>Asosliligiga ko'ra</b>: bir asosli (HCl, HNO₃), ikki asosli (H₂SO₄, H₂S), uch asosli (H₃PO₄).", '<b>By basicity</b>: monobasic (HCl, HNO₃), dibasic (H₂SO₄, H₂S), tribasic (H₃PO₄).'], ["<b>Tarkibiga ko'ra</b>: kislorodli (H₂SO₄, HNO₃) va kislorodsiz (HCl, H₂S).", '<b>By composition</b>: oxygen-containing (H₂SO₄, HNO₃) and oxygen-free (HCl, H₂S).'], ["<b>Kuchiga ko'ra</b>: kuchli (HCl, H₂SO₄, HNO₃) va kuchsiz (H₂CO₃, H₂S, sirka kislotasi).", '<b>By strength</b>: strong (HCl, H₂SO₄, HNO₃) and weak (H₂CO₃, H₂S, acetic acid).'], ["Organik kislotalar: limon, olma, sirka, sut kislotalari — meva va oziq-ovqatda.", 'Organic acids: citric, malic, acetic, lactic — in fruit and food.']],
      k: [['Asoslilik', 'Kislotadagi almashinadigan vodorod atomlari soni', 'Basicity', 'Number of replaceable hydrogen atoms']],
      z: [['H₂SO₄ — bir asosli kislota.', 'H₂SO₄ is monobasic.', 0], ['HCl — kislorodsiz kislota.', 'HCl is an oxygen-free acid.', 1], ['H₃PO₄ — uch asosli kislota.', 'H₃PO₄ is tribasic.', 1], ['Sirka kislotasi — kuchli kislota.', 'Acetic acid is a strong acid.', 0]] },

    { t: ['Kislotalarning olinishi', 'Obtaining acids'], q: ['Kislotalar qayerdan va qanday olinadi?', 'Where and how are acids obtained?'],
      i: ['Kislotalar laboratoriyada, sanoatda va tabiiy manbalardan olinadi.', 'Acids are obtained in laboratories, in industry and from natural sources.'],
      p: [["Kislotali oksid + suv → kislorodli kislota: SO₃ + H₂O → H₂SO₄; CO₂ + H₂O ⇄ H₂CO₃.", 'Acidic oxide + water → oxyacid: SO₃ + H₂O → H₂SO₄; CO₂ + H₂O ⇄ H₂CO₃.'], ["Vodorod + nometall → kislorodsiz kislota: H₂ + Cl₂ → 2HCl (suvda eritiladi).", 'Hydrogen + non-metal → oxygen-free acid: H₂ + Cl₂ → 2HCl (dissolved in water).'], ["Laboratoriyada HCl tuzga konsentrlangan sulfat kislota ta'sir ettirib olinadi: NaCl + H₂SO₄ → NaHSO₄ + HCl↑.", 'In the lab, HCl is made by treating salt with concentrated sulfuric acid: NaCl + H₂SO₄ → NaHSO₄ + HCl↑.'], ["Karbonat kislota beqaror — oson CO₂ va suvga parchalanadi (gazli ichimlikdagi pufakchalar).", 'Carbonic acid is unstable — it easily breaks into CO₂ and water (bubbles in fizzy drinks).']],
      e: ['SO₃ + H₂O → H₂SO₄', 'H₂ + Cl₂ → 2HCl', 'P₂O₅ + 3H₂O → 2H₃PO₄'],
      z: [['Kislotali oksid suv bilan kislota hosil qiladi.', 'An acidic oxide forms an acid with water.', 1], ['Karbonat kislota juda barqaror modda.', 'Carbonic acid is very stable.', 0], ['HCl ni vodorod va xlordan olish mumkin.', 'HCl can be made from hydrogen and chlorine.', 1], ['Limon kislotasi tabiiy manbadan olinadi.', 'Citric acid comes from natural sources.', 1]] },

    { t: ['Kislotalarning metallar bilan reaksiyasi', 'Reactions of acids with metals'], q: ['Qaysi metallar kislotalar bilan reaksiyaga kirishadi?', 'Which metals react with acids?'],
      i: ['Kislotalar ba\'zi metallar bilan reaksiyaga kirishib, tuz va vodorod hosil qiladi. Bu kislotalarning eng muhim xossalaridan biri.', 'Acids react with some metals to give a salt and hydrogen. This is one of the most important properties of acids.'],
      p: [["Metall + kislota → tuz + H₂↑ (faqat faollik qatorida H dan chapdagi metallar).", 'Metal + acid → salt + H₂↑ (only metals left of H in the activity series).'], ["Faollik qatori: K, Na, Ca, Mg, Al, Zn, Fe, Pb, (H), Cu, Ag, Au.", 'Activity series: K, Na, Ca, Mg, Al, Zn, Fe, Pb, (H), Cu, Ag, Au.'], ["Mg — shiddatli, Zn — o'rtacha, Fe — sekin reaksiyaga kirishadi; Cu, Ag, Au suyultirilgan HCl bilan reaksiyaga kirishmaydi.", 'Mg reacts vigorously, Zn moderately, Fe slowly; Cu, Ag, Au do not react with dilute HCl.'], ["HCl dan xloridlar, H₂SO₄ dan sulfatlar hosil bo'ladi. Fe + 2HCl → FeCl₂ + H₂↑.", 'HCl gives chlorides; H₂SO₄ gives sulfates. Fe + 2HCl → FeCl₂ + H₂↑.']],
      e: ['Mg + 2HCl → MgCl₂ + H₂↑', 'Zn + H₂SO₄ → ZnSO₄ + H₂↑'],
      k: [['Faollik qatori', 'Metallarning faolligi bo\'yicha tartibi', 'Activity series', 'Metals ordered by reactivity']],
      z: [['Vodoroddan faol metallar kislotalardan vodorodni siqib chiqaradi.', 'Metals more reactive than hydrogen displace it from acids.', 1], ['Mis suyultirilgan HCl dan vodorod ajratadi.', 'Copper releases hydrogen from dilute HCl.', 0], ['Barcha metallar kislota bilan reaksiyaga kirishadi.', 'All metals react with acids.', 0], ['Zn + H₂SO₄ da ZnSO₄ hosil bo\'ladi.', 'Zn + H₂SO₄ forms ZnSO₄.', 1]] },

    { t: ["Kislotali yog'inlar", 'Acid precipitation'], q: ["Kislotali yomg'ir qanday hosil bo'ladi va qanday zarar yetkazadi?", 'How does acid rain form and what harm does it cause?'],
      i: ["Kislotali yog'in atmosferadagi kislotali gazlar suv bug'i bilan reaksiyaga kirishganda hosil bo'ladi: yomg'ir, qor va boshqalar.", 'Acid precipitation forms when acidic gases react with water vapour in the atmosphere: rain, snow and more.'],
      p: [["Asosiy sabab: qazilma yoqilg'ilar yonganda chiqadigan <b>SO₂</b> va <b>NO₂</b>.", 'Main cause: <b>SO₂</b> and <b>NO₂</b> from burning fossil fuels.'], ["Kislotali yomg'irning pH qiymati 5,6 dan past.", 'Acid rain has a pH below 5.6.'], ["Zarari: suv havzalari nordonlashadi, baliqlar nobud bo'ladi, o'rmonlar quriydi, ohaktosh (CaCO₃) va marmar binolar yemiriladi.", 'Harm: water bodies become acidic, fish die, forests wither, limestone (CaCO₃) and marble buildings erode.'], ["Yechim: SO₂ va NO₂ chiqindilarini kamaytirish, filtrlar, toza energiya.", 'Solution: cutting SO₂ and NO₂ emissions, filters, clean energy.']],
      e: ['SO₂ + H₂O → H₂SO₃', '2SO₂ + O₂ + 2H₂O → 2H₂SO₄'],
      k: [["Kislotali yomg'ir", "pH < 5,6 bo'lgan yog'in", 'Acid rain', 'Precipitation with pH < 5.6']],
      z: [["Kislotali yomg'ir faqat CO₂ dan hosil bo'ladi.", 'Acid rain is caused only by CO₂.', 0], ["Kislotali yomg'ir suv havzalari kislotaliligini oshiradi.", 'Acid rain increases the acidity of water bodies.', 1], ["Kislotali yomg'ir faqat zavodlar yonida yog'adi.", 'Acid rain falls only near factories.', 0], ["SO₂ va NO₂ ni kamaytirish kislotali yomg'irni kamaytiradi.", 'Reducing SO₂ and NO₂ reduces acid rain.', 1]] },

    { t: ["Suvning tarkibi, agregat holatlari va tabiatda aylanishi", 'Composition of water, its states and the water cycle'], q: ['Suv nimadan iborat va tabiatda qanday aylanadi?', 'What is water made of and how does it cycle in nature?'],
      i: ["Suv — Yerdagi eng muhim moddalardan biri. U tabiatda qattiq, suyuq va gaz holatida bo'lib, bu holatlar o'rtasida uzluksiz aylanadi.", 'Water is one of Earth’s most important substances. It exists as solid, liquid and gas, continuously cycling between them.'],
      p: [["Suv molekulasi 2 ta vodorod va 1 ta kislorod atomidan iborat: <b>H₂O</b>; elektrolizda V(H₂) : V(O₂) = 2 : 1.", 'A water molecule has 2 hydrogen atoms and 1 oxygen atom: <b>H₂O</b>; in electrolysis V(H₂) : V(O₂) = 2 : 1.'], ["Muzning aniq shakli va hajmi bor; suyuq suv idish shaklini oladi; bug' — gaz.", 'Ice has a definite shape and volume; liquid water takes its container’s shape; steam is a gas.'], ["Normal bosimda suv 0 °C da muzlaydi va 100 °C da qaynaydi.", 'At normal pressure water freezes at 0 °C and boils at 100 °C.'], ["Suvning aylanishi: bug'lanish → kondensatsiya → yog'ingarchilik → yig'ilish.", 'Water cycle: evaporation → condensation → precipitation → collection.']],
      e: ['2H₂O → 2H₂↑ + O₂↑ (elektroliz / electrolysis)'],
      k: [['Kondensatsiya', "Bug'ning suyuqlikka aylanishi", 'Condensation', 'Vapour turning into liquid']],
      z: [['Suv molekulasi 2 ta H va 1 ta O atomidan iborat.', 'A water molecule has 2 H and 1 O atoms.', 1], ['Muzning aniq shakli va hajmi bor.', 'Ice has a definite shape and volume.', 1], ['Suv istalgan bosimda aynan 100 °C da qaynaydi.', 'Water always boils at exactly 100 °C at any pressure.', 0, ['100 °C — normal atmosfera bosimida; tog\'da pastroq haroratda qaynaydi.', '100 °C is at normal pressure; in mountains it boils lower.']], ['Bulutlar kondensatsiya natijasida hosil bo\'ladi.', 'Clouds form by condensation.', 1]] },

    { t: ['Suvning fizik va kimyoviy xossalari', 'Physical and chemical properties of water'], q: ['Suvning qanday noyob xossalari bor?', 'What unique properties does water have?'],
      i: ["O'ziga xos fizik xossalari tufayli suv tabiatda turli shakllarda uchraydi va hayotni ta'minlaydi.", 'Thanks to its unique physical properties, water takes many forms in nature and sustains life.'],
      p: [["Suvning zichligi <b>4 °C</b> da eng katta (1 g/mL); muz suvdan yengil — shuning uchun suv yuzasida suzadi va ko'llar tubigacha muzlamaydi.", 'Water is densest at <b>4 °C</b> (1 g/mL); ice is less dense and floats, so lakes don’t freeze to the bottom.'], ["Suv yaxshi erituvchi va issiqlik sig'imi katta — iqlimni yumshatadi.", 'Water is a good solvent with a high heat capacity — it moderates climate.'], ["Faol metallar suv bilan reaksiyaga kirishadi: 2Na + 2H₂O → 2NaOH + H₂↑.", 'Active metals react with water: 2Na + 2H₂O → 2NaOH + H₂↑.'], ["Asosli oksidlar bilan ishqor, kislotali oksidlar bilan kislota hosil qiladi: CaO + H₂O → Ca(OH)₂; CO₂ + H₂O ⇄ H₂CO₃.", 'With basic oxides it forms alkalis, with acidic oxides acids: CaO + H₂O → Ca(OH)₂; CO₂ + H₂O ⇄ H₂CO₃.']],
      e: ['2Na + 2H₂O → 2NaOH + H₂↑', 'CaO + H₂O → Ca(OH)₂'],
      z: [['Suv 0 °C da muzlaydi.', 'Water freezes at 0 °C.', 1], ['Suvning zichligi 4 °C da eng katta.', 'Water is densest at 4 °C.', 1], ['Muz suvda cho\'kadi.', 'Ice sinks in water.', 0], ['Ba\'zi faol metallar suv bilan reaksiyaga kirishadi.', 'Some active metals react with water.', 1]] },

    { t: ['Neytrallanish reaksiyalari', 'Neutralization reactions'], q: ['Kislota va asos o\'zaro ta\'sirlashganda nima sodir bo\'ladi?', 'What happens when an acid and a base react?'],
      i: ["Kislota va asos reaksiyaga kirishganda ularning xarakterli xossalari yo'qoladi va yangi moddalar — tuz va suv hosil bo'ladi.", 'When an acid and a base react, their characteristic properties disappear and new substances — a salt and water — form.'],
      p: [["Kislota + asos → tuz + suv.", 'Acid + base → salt + water.'], ["Reaksiya mohiyati: <b>H⁺ + OH⁻ → H₂O</b>.", 'Essence of the reaction: <b>H⁺ + OH⁻ → H₂O</b>.'], ["Fenolftalein ishqorda pushti, neytral va kislotali muhitda rangsiz — neytrallanish nuqtasini ko'rsatadi.", 'Phenolphthalein is pink in alkali and colourless in neutral/acid — it shows the neutral point.'], ["Hayotda: oshqozon kislotaliligini kamaytiruvchi dorilar, nordon tuproqqa ohak solish, sanoat oqovalarini zararsizlantirish.", 'In life: antacids, liming acidic soil, neutralising industrial waste water.']],
      e: ['NaOH + HCl → NaCl + H₂O', '2KOH + H₂SO₄ → K₂SO₄ + 2H₂O'],
      k: [['Neytrallanish', 'Kislota va asosdan tuz va suv hosil bo\'lishi', 'Neutralization', 'An acid and base forming salt and water'], ['Fenolftalein', 'Ishqorda pushti bo\'luvchi indikator', 'Phenolphthalein', 'An indicator that turns pink in alkali']],
      z: [['Neytrallanishda tuz va suv hosil bo\'ladi.', 'Neutralization forms salt and water.', 1], ['HCl + NaOH reaksiyasida NaCl hosil bo\'ladi.', 'HCl + NaOH forms NaCl.', 1], ['Neytrallanishda yangi modda hosil bo\'lmaydi.', 'No new substance forms in neutralization.', 0], ['Fenolftalein kislotada pushti bo\'ladi.', 'Phenolphthalein is pink in acid.', 0]] },

    { t: ['Suvning ifloslanishi va tozalash usullari', 'Water pollution and methods of purification'], q: ['Suv qanday ifloslanadi va qanday tozalanadi?', 'How does water become polluted and how is it cleaned?'],
      i: ["Suv — hayot manbai. Inson faoliyati natijasida suv havzalari ifloslanib, tabiat muvozanati buziladi va sog'liqqa xavf tug'iladi.", 'Water is the source of life. Human activity pollutes water bodies, upsetting nature’s balance and threatening health.'],
      p: [["Ifloslantiruvchilar: sanoat va maishiy oqovalar, o'g'it va pestitsidlar, neft mahsulotlari, og'ir metallar, plastik.", 'Pollutants: industrial and household waste water, fertilisers and pesticides, oil, heavy metals, plastic.'], ["Tozalash bosqichlari: <b>tindirish</b> → <b>filtrlash</b> (qum, ko'mir) → <b>zararsizlantirish</b> (xlor, ozon, UB nur).", 'Purification stages: <b>sedimentation</b> → <b>filtration</b> (sand, charcoal) → <b>disinfection</b> (chlorine, ozone, UV).'], ["Uyda: suvni qaynatish mikroblarni o'ldiradi.", 'At home: boiling water kills germs.'], ["Faollashtirilgan ko'mir erigan bo'yoq va hidlarni adsorbsiyalaydi.", 'Activated charcoal adsorbs dissolved colours and odours.']],
      k: [['Zararsizlantirish', 'Suvdagi mikroblarni yo\'q qilish', 'Disinfection', 'Killing germs in water'], ['Adsorbsiya', 'Moddalarning sirtga yutilishi', 'Adsorption', 'Substances sticking to a surface']],
      z: [['Tindirishda og\'ir zarrachalar cho\'kadi.', 'In sedimentation, heavy particles sink.', 1], ['Xlor suvni zararsizlantiradi.', 'Chlorine disinfects water.', 1], ['Tiniq suvda mikrob bo\'lmaydi.', 'Clear water never contains germs.', 0], ['Qaynatish mikroblarni o\'ldiradi.', 'Boiling kills germs.', 1]] },

    { t: ['Suvning qattiqligi va uni yumshatish usullari', 'Water hardness and methods of softening'], q: ['Suvni nima qattiq qiladi va uni qanday yumshatamiz?', 'What makes water hard and how do we soften it?'],
      i: ["Tabiatdagi suv har doim ham sof va yumshoq emas. Yer osti va yer usti suvlarida erigan kalsiy (Ca²⁺) va magniy (Mg²⁺) ionlari suvni qattiq qiladi.", 'Natural water is not always pure and soft. Dissolved calcium (Ca²⁺) and magnesium (Mg²⁺) ions make it hard.'],
      p: [["Qattiq suvda sovun yaxshi ko'piklanmaydi, choynakda quyqa (CaCO₃) hosil bo'ladi.", 'In hard water soap lathers poorly and kettles build up limescale (CaCO₃).'], ["<b>Vaqtinchalik qattiqlik</b> — Ca(HCO₃)₂ va Mg(HCO₃)₂ — qaynatish bilan yo'qoladi: Ca(HCO₃)₂ → CaCO₃↓ + H₂O + CO₂↑.", '<b>Temporary hardness</b> — Ca(HCO₃)₂ and Mg(HCO₃)₂ — is removed by boiling: Ca(HCO₃)₂ → CaCO₃↓ + H₂O + CO₂↑.'], ["<b>Doimiy qattiqlik</b> — sulfat va xloridlar — qaynatish bilan yo'qolmaydi; soda (Na₂CO₃) qo'shib yumshatiladi.", '<b>Permanent hardness</b> — sulfates and chlorides — is not removed by boiling; washing soda (Na₂CO₃) softens it.'], ["Boshqa usullar: ion almashinish (Ca²⁺ va Mg²⁺ Na⁺ ga almashtiriladi), distillash.", 'Other methods: ion exchange (Ca²⁺, Mg²⁺ swapped for Na⁺), distillation.']],
      e: ['Ca(HCO₃)₂ → CaCO₃↓ + H₂O + CO₂↑ (qaynatish / boiling)', 'CaSO₄ + Na₂CO₃ → CaCO₃↓ + Na₂SO₄'],
      k: [['Qattiq suv', 'Ca²⁺ va Mg²⁺ ionlariga boy suv', 'Hard water', 'Water rich in Ca²⁺ and Mg²⁺'], ['Quyqa', "Qaynatilganda hosil bo'luvchi CaCO₃ qatlami", 'Limescale', 'The CaCO₃ deposit formed on boiling']],
      z: [['Ca(HCO₃)₂ qizdirilganda parchalanadi.', 'Ca(HCO₃)₂ decomposes on heating.', 1], ['Ikkala qattiqlik turi ham qaynatish bilan to\'liq yo\'qoladi.', 'Both types of hardness are fully removed by boiling.', 0], ['Ion almashinishda Ca²⁺ va Mg²⁺ boshqa ionlarga almashtiriladi.', 'Ion exchange replaces Ca²⁺ and Mg²⁺ with other ions.', 1], ["Distillashda suv avval bug'lanib, so'ng kondensatsiyalanadi.", 'In distillation, water is evaporated then condensed.', 1]] },

    { t: ['Tirik organizmlardagi kimyoviy elementlar', 'Chemical elements in living organisms'], q: ['Tanamiz qaysi elementlardan tashkil topgan?', 'Which elements make up our bodies?'],
      i: ["Odamlar, hayvonlar, o'simliklar va mikroorganizmlar uglerod, vodorod, kislorod, azot, kalsiy, fosfor va boshqa elementlardan iborat.", 'Humans, animals, plants and microbes are made of carbon, hydrogen, oxygen, nitrogen, calcium, phosphorus and other elements.'],
      p: [["<b>Makroelementlar</b> (ko'p miqdorda): O, C, H, N (tanamizning ≈ 96%), Ca, P, K, S, Na, Cl, Mg.", '<b>Macroelements</b> (large amounts): O, C, H, N (≈ 96% of the body), Ca, P, K, S, Na, Cl, Mg.'], ["<b>Mikroelementlar</b> (juda oz miqdorda): Fe, Zn, I, Cu, F, Mn, Se — lekin hayotiy muhim.", '<b>Microelements</b> (tiny amounts): Fe, Zn, I, Cu, F, Mn, Se — but vital.'], ["Kislorod tanamizda eng ko'p tarqalgan element (massasi bo'yicha ≈ 65%).", 'Oxygen is the most abundant element in the body (≈ 65% by mass).'], ["Temir — gemoglobin tarkibida kislorod tashiydi; yod — qalqonsimon bez gormonlari uchun; kalsiy — suyaklar uchun.", 'Iron carries oxygen in haemoglobin; iodine is needed for thyroid hormones; calcium for bones.']],
      k: [['Makroelement', "Organizmda ko'p miqdordagi element", 'Macroelement', 'An element present in large amounts'], ['Mikroelement', 'Organizmda juda oz, lekin zarur element', 'Microelement', 'An element needed in tiny amounts']],
      z: [['Mikroelementlar tirik organizmlar uchun muhim emas.', 'Microelements are not important for living things.', 0], ['Tanamizda eng ko\'p kislorod bor.', 'Oxygen is the most abundant element in the body.', 1], ['Yod faqat o\'simliklarda uchraydi.', 'Iodine is found only in plants.', 0], ['Temir kislorod tashishda ishtirok etadi.', 'Iron is involved in oxygen transport.', 1]] },

    { t: ['Oqsillar, yog\'lar, uglevodlar va vitaminlar', 'Proteins, fats, carbohydrates and vitamins'], q: ['Bu organik moddalar organizmda qanday vazifa bajaradi?', 'What roles do these organic substances play?'],
      i: ["Oqsillar, yog'lar, uglevodlar va vitaminlar — tirik organizmlar uchun zarur organik moddalar. Ular hujayralar tuzilishida qatnashadi va energiya manbai bo'ladi.", 'Proteins, fats, carbohydrates and vitamins are essential organic substances. They build cells and provide energy.'],
      p: [["<b>Oqsillar</b> aminokislotalardan tuzilgan; mushak, ferment, gormon va antitanalar tarkibida.", '<b>Proteins</b> are made of amino acids; found in muscles, enzymes, hormones and antibodies.'], ["<b>Uglevodlar</b> (glyukoza, kraxmal, selluloza) — asosiy energiya manbai; o'simlik mahsulotlarida ko'p.", '<b>Carbohydrates</b> (glucose, starch, cellulose) — the main energy source; abundant in plant foods.'], ["<b>Yog'lar</b> — zaxira energiya (1 g yog' ≈ 9 kkal); suvda erimaydi, chunki molekulasi qutbsiz.", '<b>Fats</b> — energy stores (1 g ≈ 9 kcal); insoluble in water because their molecules are non-polar.'], ["<b>Vitaminlar</b> juda oz miqdorda kerak, chunki ular fermentlar ishini boshqaradi.", '<b>Vitamins</b> are needed in tiny amounts because they regulate enzyme action.']],
      k: [['Aminokislota', 'Oqsilning tarkibiy qismi', 'Amino acid', 'A building block of protein'], ['Kraxmal', "O'simliklardagi zaxira uglevod", 'Starch', 'A storage carbohydrate in plants']],
      z: [['Oqsillar aminokislotalardan tuzilgan.', 'Proteins are made of amino acids.', 1], ["Yog'lar suvda yaxshi eriydi.", 'Fats dissolve well in water.', 0], ["O'simlik mahsulotlarida uglevodlar ko'p.", 'Plant foods are rich in carbohydrates.', 1], ["Vitaminlar ko'p miqdorda kerak.", 'Vitamins are needed in large amounts.', 0]] },

    { t: ['Inson hayotida minerallarning ahamiyati', 'Importance of minerals in human life'], q: ['Mineral elementlar organizm uchun nima uchun zarur?', 'Why does the body need mineral elements?'],
      i: ["Mineral elementlar — tirik organizmlar uchun zarur noorganik elementlar va ularning ionlari. Ular ovqat bilan kiradi va oz miqdorda bo'lsa ham, muhim vazifalarni bajaradi.", 'Minerals are inorganic elements and ions that living things need. They come from food and, though needed in small amounts, do vital jobs.'],
      p: [["<b>Kalsiy (Ca)</b> — suyak va tishlarning mineral tarkibi; sut, pishloq, qatiq.", '<b>Calcium (Ca)</b> — the mineral of bones and teeth; milk, cheese, yoghurt.'], ["<b>Temir (Fe)</b> — kislorod tashish; yetishmasa kamqonlik va holsizlik; go'sht, jigar, dukkaklilar.", '<b>Iron (Fe)</b> — oxygen transport; deficiency causes anaemia and fatigue; meat, liver, beans.'], ["<b>Kaliy va natriy</b> — mushak va nerv tizimi ishi; <b>rux (Zn)</b> — immunitet va yara bitishi.", '<b>Potassium and sodium</b> — muscle and nerve function; <b>zinc (Zn)</b> — immunity and wound healing.'], ["<b>Yod</b> — qalqonsimon bez; yodlangan tuz ishlatish tavsiya etiladi. <b>Ftor</b> — tish emalini mustahkamlaydi.", '<b>Iodine</b> — thyroid gland; iodised salt is recommended. <b>Fluorine</b> strengthens enamel.']],
      k: [['Kamqonlik', 'Qonda gemoglobin yetishmasligi', 'Anaemia', 'Lack of haemoglobin in the blood']],
      z: [['Kalsiy suyak va tishlar uchun muhim.', 'Calcium is important for bones and teeth.', 1], ['Temir organizmda kislorod tashishda ishtirok etadi.', 'Iron is involved in oxygen transport.', 1], ['Mineral elementlar organizmda o\'z-o\'zidan hosil bo\'ladi.', 'The body makes its own minerals.', 0], ['Yodlangan tuz yod yetishmasligining oldini oladi.', 'Iodised salt prevents iodine deficiency.', 1]] },

    { t: ['Olma tarkibini aniqlash', 'Identifying the composition of an apple'], q: ['Oddiy kuzatish va reaksiyalar bilan olma tarkibini qanday aniqlaymiz?', 'How can simple observations and reactions reveal what an apple contains?'],
      i: ["Olma — mazali va foydali meva. Unda turli kimyoviy moddalar bor. Bu darsda ularni oddiy kuzatish va xarakterli reaksiyalar yordamida aniqlaymiz.", 'Apples are tasty and healthy and contain many substances. We identify them using simple observation and characteristic reactions.'],
      p: [["<b>Kuzatish</b>: olma shirali — uning ≈ 85% i suv.", '<b>Observation</b>: apples are juicy — about 85% water.'], ["<b>Indikator</b> bilan: olma sharbati kislotali muhit ko'rsatadi — unda organik kislotalar (olma kislotasi) bor.", '<b>Indicator</b>: apple juice shows an acidic medium — it contains organic acids (malic acid).'], ["<b>Yod</b> bilan: pishmagan olma ko'k-qora rang beradi — kraxmal bor; pishganida kraxmal shakarga aylanadi.", '<b>Iodine</b>: unripe apple turns blue-black — starch present; when ripe, starch turns into sugar.'], ["Kesilgan olmaning qorayishi — undagi temir birikmalari va fenollarning havo kislorodi bilan oksidlanishi.", 'A cut apple browns as its phenols (and iron compounds) are oxidised by air.']],
      k: [['Olma kislotasi', 'Olmadagi organik kislota', 'Malic acid', 'The organic acid in apples']],
      f: ['Kesilgan olmaga limon sharbati surtilsa, u sekin qorayadi — C vitamini oksidlanishni sekinlashtiradi.', 'Lemon juice slows a cut apple’s browning — vitamin C slows oxidation.'],
      z: [["Olmada suv ko'p.", 'Apples contain a lot of water.', 1], ['Indikator olmadagi organik kislotalarni aniqlashga yordam beradi.', 'An indicator helps detect organic acids in apples.', 1], ["Pishgan olmada kraxmal pishmaganidagidan ko'p.", 'Ripe apples contain more starch than unripe ones.', 0], ['Yod kraxmal bilan ko\'k-qora rang beradi.', 'Iodine turns blue-black with starch.', 1]] },

    { t: ['Geologik kimyoviy birikmalar', 'Geological chemical compounds'], q: ['Yer po\'sti qanday birikmalardan tuzilgan?', 'What compounds make up Earth’s crust?'],
      i: ["Yer po'sti turli kimyoviy birikma va elementlardan iborat bo'lib, ular minerallar va tog' jinslari shaklida uchraydi. Ular xomashyo, metall va kimyoviy mahsulotlar manbai.", 'Earth’s crust is made of compounds and elements found as minerals and rocks — sources of raw materials, metals and chemicals.'],
      p: [["Yer po'stidagi eng ko'p elementlar: O (≈ 46%), Si (≈ 28%), Al, Fe, Ca, Na, K, Mg.", 'Most abundant crustal elements: O (≈ 46%), Si (≈ 28%), Al, Fe, Ca, Na, K, Mg.'], ["Oksidlar: kvars (SiO₂), gematit (Fe₂O₃), boksit (Al₂O₃); karbonatlar: ohaktosh, marmar (CaCO₃).", 'Oxides: quartz (SiO₂), haematite (Fe₂O₃), bauxite (Al₂O₃); carbonates: limestone, marble (CaCO₃).'], ["Sulfidlar: pirit (FeS₂), xalkopirit (CuFeS₂); tuzlar: galit (NaCl), gips (CaSO₄·2H₂O).", 'Sulfides: pyrite (FeS₂), chalcopyrite (CuFeS₂); salts: halite (NaCl), gypsum (CaSO₄·2H₂O).'], ["Minerallar millionlab yillar davomida magma sovishi, cho'kindilar to'planishi va bosim ta'sirida hosil bo'ladi.", 'Minerals form over millions of years from cooling magma, settling sediments and pressure.']],
      k: [['Mineral', "Tabiiy, ma'lum tarkibli qattiq modda", 'Mineral', 'A natural solid with a definite composition'], ["Tog' jinsi", 'Minerallar aralashmasi', 'Rock', 'A mixture of minerals']],
      z: [["Yer po'stida eng ko'p element — kislorod.", 'Oxygen is the most abundant crustal element.', 1], ['Marmar — CaCO₃.', 'Marble is CaCO₃.', 1], ['Galit — temir rudasi.', 'Halite is an iron ore.', 0, ['Galit — osh tuzi (NaCl).', 'Halite is rock salt (NaCl).']], ['Kvars formulasi SiO₂.', 'Quartz is SiO₂.', 1]] },

    { t: ["O'zbekistonning foydali qazilmalari va konlari", 'Useful minerals and deposits in Uzbekistan'], q: ["O'zbekistonda qanday foydali qazilmalar bor?", 'What useful minerals does Uzbekistan have?'],
      i: ["O'zbekiston tabiiy resurslarga boy. Yerimizdagi foydali qazilmalar sanoat, energetika va aholi ehtiyojlari uchun muhim xomashyo manbai.", 'Uzbekistan is rich in natural resources — an important source of raw materials for industry, energy and daily needs.'],
      p: [["<b>Oltin</b>: Muruntov (Navoiy viloyati) — dunyodagi eng yirik oltin konlaridan biri; Navoiy kon-metallurgiya kombinati.", '<b>Gold</b>: Muruntau (Navoi region) — one of the world’s largest gold deposits; Navoi Mining and Metallurgical Combine.'], ["<b>Mis, rux, qo'rg'oshin</b>: Olmaliq (Qalmoqir, Sariqcheku konlari).", '<b>Copper, zinc, lead</b>: Almalyk (Kalmakyr, Sarycheku deposits).'], ["<b>Tabiiy gaz va neft</b>: Gazli, Sho'rtan, Muborak, Ustyurt; <b>uran</b> — Navoiy viloyati.", '<b>Natural gas and oil</b>: Gazli, Shurtan, Mubarek, Ustyurt; <b>uranium</b> — Navoi region.'], ["<b>Ko'mir</b>: Angren; <b>kaliy tuzlari</b>: Tyubegatan (Dehqonobod); <b>fosforitlar</b>: Qizilqum.", '<b>Coal</b>: Angren; <b>potash</b>: Tyubegatan (Dekhkanabad); <b>phosphorites</b>: Kyzylkum.']],
      k: [['Kon', "Foydali qazilma to'plangan joy", 'Deposit', 'A place where a useful mineral is concentrated']],
      f: ["Muruntov oltin koni karyeri shunchalik kattaki, uni kosmosdan ham ko'rish mumkin.", 'The Muruntau gold pit is so large it can be seen from space.'],
      z: [["Muruntov — oltin koni.", 'Muruntau is a gold deposit.', 1], ["Olmaliqda mis qazib olinadi.", 'Copper is mined at Almalyk.', 1], ["Angren — ko'mir koni.", 'Angren is a coal deposit.', 1], ["O'zbekistonda tabiiy gaz yo'q.", 'Uzbekistan has no natural gas.', 0]] },

    { t: ['Foydali qazilmalarni qazib olishning ekologik jihatlari', 'Ecological aspects of extracting useful minerals'], q: ['Qazib olish tabiatga qanday ta\'sir qiladi?', 'How does mining affect nature?'],
      i: ["Foydali qazilmalar hayotimiz uchun juda muhim. Ammo ularni qazib olish, qayta ishlash va ishlatish tabiatga salbiy ta'sir ko'rsatishi mumkin.", 'Minerals are vital for our lives, but mining, processing and using them can harm nature.'],
      p: [["Asosiy bosqichlar: qidiruv → qazib olish → boyitish → qayta ishlash → tashish.", 'Main stages: exploration → extraction → concentration → processing → transport.'], ["Salbiy ta'sirlar: yer va landshaft buziladi, chang va zaharli gazlar chiqadi, suv va tuproq og'ir metallar bilan ifloslanadi.", 'Negative effects: land and landscape damage, dust and toxic gases, water and soil polluted by heavy metals.'], ["Chiqindi uyumlari (ag'darmalar) va tindirgichlar xavf manbai bo'lishi mumkin.", 'Waste heaps and tailings ponds can be hazardous.'], ["Yechim: rekultivatsiya (yerni qayta tiklash), filtrlar, suvni qayta ishlatish, metallarni qayta ishlash, tejamkorlik.", 'Solutions: land reclamation, filters, water recycling, metal recycling, using resources wisely.']],
      k: [['Rekultivatsiya', "Buzilgan yerni qayta tiklash", 'Reclamation', 'Restoring damaged land']],
      z: [['Qazib olish tuproq va suvni ifloslantirishi mumkin.', 'Mining can pollute soil and water.', 1], ["Rekultivatsiya — yerni qayta tiklash.", 'Reclamation means restoring land.', 1], ["Metallarni qayta ishlash qazib olishni kamaytiradi.", 'Recycling metals reduces mining.', 1], ["Qazib olish tabiatga hech qanday ta'sir qilmaydi.", 'Mining has no effect on nature.', 0]] },

    { t: ['Barqaror rivojlanish maqsadlari', 'Sustainable Development Goals'], q: ['Barqaror rivojlanish maqsadlarida kimyoning o\'rni qanday?', 'What role does chemistry play in the Sustainable Development Goals?'],
      i: ["Barqaror rivojlanish maqsadlari (BRM) — BMTga a'zo davlatlar tomonidan 2015-yilda qabul qilingan va 2030-yilgacha erishilishi kerak bo'lgan 17 ta global maqsad.", 'The Sustainable Development Goals (SDGs) are 17 global goals adopted by UN member states in 2015, to be achieved by 2030.'],
      p: [["Maqsadlar iqtisodiy o'sish, ijtimoiy farovonlik va atrof-muhitni muhofaza qilishni muvozanatlaydi.", 'They balance economic growth, social well-being and environmental protection.'], ["6-maqsad — toza suv va sanitariya: kimyo suvni tozalash usullarini yaratadi.", 'Goal 6 — clean water and sanitation: chemistry creates water purification methods.'], ["7-maqsad — arzon va toza energiya: quyosh panellari, batareyalar, vodorod yoqilg'isi.", 'Goal 7 — affordable, clean energy: solar panels, batteries, hydrogen fuel.'], ["12-maqsad — mas'uliyatli iste'mol (qayta ishlash), 13-maqsad — iqlim o'zgarishiga qarshi kurash (CO₂ ni kamaytirish).", 'Goal 12 — responsible consumption (recycling); Goal 13 — climate action (cutting CO₂).']],
      k: [['BRM', 'Barqaror rivojlanish maqsadlari (17 ta)', 'SDGs', 'Sustainable Development Goals (17)']],
      f: ['Har birimiz BRMga hissa qo\'sha olamiz: suv va energiyani tejash, chiqindini saralash, daraxt ekish.', 'Each of us can help the SDGs: save water and energy, sort waste, plant trees.'],
      z: [['BRM 2015-yilda qabul qilingan.', 'The SDGs were adopted in 2015.', 1], ['BRM da 17 ta maqsad bor.', 'There are 17 SDGs.', 1], ['6-maqsad toza suv bilan bog\'liq.', 'Goal 6 is about clean water.', 1], ['BRM 2050-yilgacha erishilishi kerak.', 'The SDGs are due by 2050.', 0]] },
  ];
  const units = [[1, 'Kirish va laboratoriya ishi', 'Introduction and lab work'], [7, 'Moddalar va aralashmalar', 'Substances and mixtures'], [10, 'Atom tuzilishi', 'Atomic structure'], [22, 'Valentlik, formula va mol', 'Valency, formulas and the mole'], [35, 'Davriy jadval', 'The periodic table'], [39, 'Havo, kislorod va oksidlar', 'Air, oxygen and oxides'], [52, 'Vodorod va kislotalar', 'Hydrogen and acids'], [60, 'Suv', 'Water'], [65, 'Hayot kimyosi', 'Chemistry of life'], [69, "Yer boyliklari va barqaror rivojlanish", 'Earth’s resources and sustainability']];
  const o = (a) => (a ? { uz: a[0], en: a[1] } : null);
  BOOKS.g7 = {
    units: units.map((u) => ({ from: u[0], t: { uz: u[1], en: u[2] } })),
    lessons: R.map((x) => ({ t: o(x.t), q: o(x.q), intro: x.i ? [o(x.i)] : [], pts: (x.p || []).map(o), terms: (x.k || []).map((k) => [{ uz: k[0], en: k[2] }, { uz: k[1], en: k[3] }]), fact: o(x.f), eq: x.e, quiz: (x.z || []).map((z) => [{ uz: z[0], en: z[1] }, !!z[2], z[3] ? o(z[3]) : null]) }))
  };
})();
